"use client";

/* The portal shell, ported VERBATIM from the design sandbox.

   Only the data source differs: the sandbox read NAV and USER out of a fixtures
   file, here the nav points at the real route tree and the user comes from the
   session. Every class, size and colour below is the sandbox's — if this drifts
   from /opt/nexion-ui/components/Shell.tsx, this file is the one that is wrong. */

export type User = { first: string; email: string; balanceCents: number };

/* Live counts for the rail's badges, keyed by href. The design's badges are a
   mix of the two kinds and they must not be confused: "FREE" and "AI" are
   STATIC labels that belong to the nav definition, while an unread count is
   state. A count of zero renders no badge at all — a grey "0" beside Mailboxes
   reads as a broken feature, not as an empty inbox. */
export type Badges = Record<string, number>;

import { useEffect, useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { Icon } from "./Icon";
import { NotificationsPanel, type Note } from "./Banners";
import { Wordmark, Logo } from "./Logo";
import { NAV, activeNavHref, type NavItem } from "@/lib/nx/nav";
import { CommandPalette } from "@/components/portal/CommandPalette";
import { TerminalDockProvider } from "@/components/customer/terminal/TerminalDock";
import { CurrencySwitcher } from "@/components/currency/CurrencySwitcher";
import { ThemeToggle } from "./ThemeToggle";
import { BugReportButton } from "./BugReportButton";
import { AuroraBg } from "./AuroraBg";
import { PlateBg } from "./PlateBg";
import { GlobeBg } from "./GlobeBg";
import { ComposeProvider } from "@/components/customer/mail/ComposeProvider";
import { logout } from "@/lib/actions";
import { MatrixPanel } from "./MatrixPanel";
import VisitTracker from "@/components/VisitTracker";

/* The live portal ships a flat 56-item sidebar that never collapses and has no
   mobile treatment at all. This rail groups by purpose, drops to an icon-only
   strip on medium screens, and becomes a drawer plus a bottom tab bar on
   phones — the three breakpoints the design has to survive. */

const GROUPS = ["Overview", "Compute", "Build", "Tools", "Network", "Mail", "Account"];
const MOBILE_TABS = ["/dashboard", "/deploy", "/servers", "/billing"];

/* Flattened once for the ⌘K palette (components/portal/CommandPalette.tsx,
   shared with the live portal's Shell) — it wants {label, href, section},
   not the grouped NavItem shape the rail iterates over. */
const FLAT_NAV = NAV.map((n) => ({ label: n.label, href: n.href, section: n.group }));

/* The visible "Search anything…" bar's click handler. CommandPalette owns its
   open state privately and exposes no prop to set it from outside — the only
   way in is the same ⌘K/Ctrl+K keydown it already listens for globally, so a
   click dispatches that exact event rather than the palette needing a second,
   parallel way to open. Without this, the bar rendered a real search affordance
   (icon, placeholder, ⌘K hint) that a click on it did nothing at all — the
   keyboard shortcut worked, but nobody who doesn't already know it would ever
   find that out. */
function openCommandPalette() {
  window.dispatchEvent(new KeyboardEvent("keydown", { key: "k", metaKey: true }));
}

function NavLink({ href, icon, label, badge, active, compact }: {
  href: string; icon: string; label: string; badge?: string; active: boolean; compact: boolean;
}) {
  return (
    <Link
      href={href}
      aria-current={active ? "page" : undefined}
      title={compact ? label : undefined}
      className={
        "nx-navlink group relative flex items-center rounded-[10px] transition-colors " +
        (compact ? "h-10 w-10 justify-center" : "h-[38px] gap-3 px-3") + " " +
        (active ? "nx-navlink-on" : "text-tx-dim hover:text-white")
      }
    >
      {/* 30% down from 19: the rail is the one place an icon repeats twenty times
          down a column, so it carries weight the page-level marks do not.
          Rest-vs-active glow (every icon keeps its own tone; rest is just
          quieter, via .nx-navlink:not(.nx-navlink-on) .nx-ico in globals.css)
          lives in CSS, not here — nothing else needed at this call site. */}
      <Icon name={icon} size={13} />
      {!compact && (
        <>
          <span className="flex-1 text-[13.5px] font-semibold">{label}</span>
          {badge && (
            <span className="rounded-[5px] bg-[rgba(140,58,233,0.22)] px-1.5 py-0.5 text-[9.5px] font-bold tracking-wide text-[#bfa8ee]">
              {badge}
            </span>
          )}
        </>
      )}
    </Link>
  );
}

function Rail({ compact, onNavigate, badges }: { compact: boolean; onNavigate?: () => void; badges: Badges }) {
  const path = usePathname();
  const activeHref = activeNavHref(path);

      })}
    </nav>
  );
}

function Balance({ user }: { user: User }) {
  return (
    <div className="mx-3 mb-3 rounded-[12px] border border-[rgba(72,148,255,0.20)] bg-[linear-gradient(158deg,rgba(20,197,228,0.07),rgba(58,30,150,0.11)_55%,rgba(4,20,54,0.86))] p-3 shadow-[inset_0_1px_0_rgba(255,255,255,0.05)]">
      <div className="flex items-center gap-2">
        <Icon name="card" size={13} />
        <span className="text-[9.5px] font-bold uppercase tracking-[0.10em] text-tx-dim">
          Account balance
        </span>
      </div>
      <div className="mt-1.5 flex items-baseline justify-between gap-2">
        <span className="num bg-[linear-gradient(96deg,#3fbcd8,#8fb0e8)] bg-clip-text text-[22px] text-transparent">
          ${(user.balanceCents / 100).toLocaleString("en-US", { minimumFractionDigits: 2 })}
        </span>
        <Link href="/dashboard/billing" className="text-[10.8px] font-semibold text-[#84d3e6] hover:text-white">Add funds</Link>
      </div>
    </div>
  );
}

function ShellInner({ children, user, badges, notifications, matrixPanel }: {
  children: React.ReactNode; user: User; badges: Badges; notifications: Note[];
  /** The persistent Matrix workspace — see where it renders, below. */
  matrixPanel?: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const [notesOpen, setNotesOpen] = useState(false);
  /* Held locally so "mark all read" lands instantly. The server is told too,
     but the reader should never wait on a round-trip to see a badge clear. */
  const [notes, setNotes] = useState<Note[]>(notifications);
  const unread = notes.filter((n) => !n.readAt).length;

  /* Local only. The durable write is the panel's `markNotificationsRead`
     server action; this is what clears the badge without waiting for it. */
  function markAllRead() {
    const now = new Date().toISOString();
    setNotes((ns) => ns.map((n) => (n.readAt ? n : { ...n, readAt: now })));
  }

  /* Publish this rail's real width, the way components/portal/Shell.tsx does
     for the live portal. Fixed chrome mounted OUTSIDE the shell subtree — the
     terminal dock, MatrixProvider — offsets itself by `--nx-rail-w` and falls
     back to 15rem when nobody sets it. Only the portal shell ever did, so on
     Nexion the dock sat at 240px against a rail that is 76px at lg and 248px
     at xl: a 164px dead gutter down its left, then an 8px overlap. Same shape
     as the providers this shell kept dropping — a thing the portal shell owns
     that was never ported.

     Driven by matchMedia rather than CSS because the value has to land on
     documentElement: the dock is a sibling of the shell root, so it cannot
     inherit a variable declared on it, and the portal shell writes this as an
     inline style, which a stylesheet rule could never outrank. */
  useEffect(() => {
    const lg = window.matchMedia("(min-width: 1024px)");
    const xl = window.matchMedia("(min-width: 1280px)");
    const publish = () => {
      document.documentElement.style.setProperty(
        "--nx-rail-w",
        xl.matches ? "248px" : lg.matches ? "76px" : "0px"
      );
    };
    publish();
    lg.addEventListener("change", publish);
    xl.addEventListener("change", publish);
    return () => {
      lg.removeEventListener("change", publish);
      xl.removeEventListener("change", publish);
    };
  }, []);
  const path = usePathname();
  const activeHref = activeNavHref(path);
  /* Pages that mount a PlateBg. The rail has to know: over a plate it is glass,
     everywhere else it stays the solid panel it has always been. */
  const plated = path.startsWith("/dashboard/refer");
  /* App-frame routes. Most pages are documents: they flow, and the window
     scrolls them. The mail client is an application surface — rail, list and
     reading pane each scroll independently — so it must be handed exactly the
     viewport it has left and never make the page itself scroll. That means no
     <main> padding (it sits flush against the rail and the header) and a real
     height rather than `flex-1` against a `min-h-dvh` parent, which only grows. */
  const appFrame = path.startsWith("/dashboard/mail");

  return (
    <div className="nx-shell-root relative flex">
      <VisitTracker kind="portal" />
      {/* Shared with the live portal's Shell (components/portal/CommandPalette.tsx)
          — it manages its own open state and already listens for ⌘K/Ctrl+K
          globally, so mounting it here is what makes that shortcut work at all
          on this shell. The visible "Search anything…" bar below still needs
          its own click handler (see `openPalette`) since the palette has no
          externally-settable `open` prop to call into directly. */}
      <CommandPalette nav={FLAT_NAV} />
      {/* Route-aware backdrop. The paths are v2's, not the sandbox's: every
          portal screen lives under /dashboard here, so the sandbox's
          `startsWith("/deploy")` never matched and the deploy wizard lost its
          globe. Order matters — the deploy check must come BEFORE the general
          /dashboard one, which deliberately draws nothing (the rack's streams
          already carry that page). */}
      {path.startsWith("/dashboard/deploy") ? <GlobeBg />
        : plated
          ? /* No background image at all. Every plate I put here was wrong in
               a different way — the ones I built from NASA frames went muddy
               green, and the brand ribbon still read as a picture pasted
               behind the content. The field is the canvas alone now: drawn
               light, no photograph. */
            <PlateBg seed={0} />
        : path.startsWith("/dashboard") ? null
        : <AuroraBg />}
      {/* desktop rail — full at xl, icon-only from lg */}
      {/* The rail is the same on every page, full stop. It briefly became glass
          on plated routes so the backdrop would read through it; that was not
          wanted — the nav is chrome and should not change under the content. */}
      {/* Two layers, on purpose. `nx-shell-rail`'s fixed `calc(100dvh - …)`
          height has to live on something so the nav+balance stack stays
          pinned to one screen's worth — but putting that height (and the
          `sticky`) directly on the ISLAND meant the island's own box, and so
          its opaque dark plate (`.nx-dark-island`'s `background-color`), only
          ever covered ONE viewport of the document. Past that first screen,
          scrolling any page taller than the fold ran the rail's own box out
          from under itself, and the page ground (light in light mode) showed
          through in the gutter below it — the reported "white space under the
          sidebar". The OUTER `<aside>` is a plain flex item with no height of
          its own, so it stretches (the flex default) to match the content
          column beside it — real height, real background, for the whole
          scrollable page. The INNER div is what actually sticks and gets
          capped to one viewport, exactly as the whole element used to. */}
      <aside className="nx-dark-island hidden shrink-0 flex-col border-r border-rim-soft lg:flex lg:w-[76px] xl:w-[248px]">
        <div className="sticky top-0 z-20 flex nx-shell-rail flex-col bg-side/80 backdrop-blur">
          <div className="flex h-[72px] items-center px-4 xl:px-5">
            <span className="hidden xl:block"><Wordmark size={38} /></span>
            <span className="xl:hidden"><Logo size={36} /></span>
          </div>
          <div className="hidden min-h-0 flex-1 xl:block"><Rail compact={false} badges={badges} /></div>
          <div className="min-h-0 flex-1 xl:hidden"><Rail compact badges={badges} /></div>
          <div className="hidden xl:block"><Balance user={user} /></div>
        </div>
      </aside>

      {/* mobile drawer */}
      {open && (
        <div className="fixed inset-0 z-50 lg:hidden">
          <button aria-label="Close menu" onClick={() => setOpen(false)}
                  className="absolute inset-0 bg-black/70 backdrop-blur-sm" />
          <aside className="nx-dark-island absolute inset-y-0 left-0 flex w-[272px] flex-col border-r border-rim-soft bg-side">
            <div className="flex h-[64px] items-center justify-between px-4">
              <Wordmark size={34} />
              <button onClick={() => setOpen(false)} className="p-2 text-tx-dim" aria-label="Close">
                <Icon name="xcircle" size={20} />
              </button>
            </div>
            <div className="min-h-0 flex-1"><Rail compact={false} onNavigate={() => setOpen(false)} badges={badges} /></div>
            <Balance user={user} />
          </aside>
        </div>
      )}

      <div className="relative z-10 flex min-w-0 flex-1 flex-col">
        {/* topbar */}
        <header className="nx-dark-island sticky top-0 z-30 flex h-[64px] items-center gap-3 border-b border-rim-soft bg-bg/70 px-4 backdrop-blur sm:px-6 lg:h-[72px]">
          <button onClick={() => setOpen(true)} aria-label="Open menu"
                  className="grid h-10 w-10 place-items-center rounded-[10px] border border-rim-hi lg:hidden">
            <Icon name="grid" size={18} />
          </button>
          <button
            type="button"
            onClick={openCommandPalette}
            aria-label="Search anything"
            className="field h-10 min-w-0 flex-1 max-w-[440px] text-left"
          >
            <Icon name="search" size={16} />
            <span className="trunc flex-1 text-[13px] text-tx-faint">Search anything…</span>
            <kbd className="mono hidden rounded-[5px] border border-rim-hi px-1.5 py-0.5 text-[10px] text-tx-dim sm:block">
              ⌘K
            </kbd>
          </button>
          <div className="ml-auto flex items-center gap-2 sm:gap-3">
            {/* The display-currency switcher, with its country flags. The portal
                has had geo currency for a while and `CurrencyProvider` is
                mounted in app/dashboard/layout.tsx, but this rebuilt shell
                dropped the control the old one carried — so the currency was
                detected and then unchangeable. Hidden on the narrowest screens,
                where the header has no room for it. */}
            <span className="hidden sm:block"><CurrencySwitcher /></span>
            <ThemeToggle />
            <BugReportButton />
            <div className="relative">
              <button onClick={() => setNotesOpen((v) => !v)}
                      aria-label="Notifications" aria-expanded={notesOpen}
                      className="relative grid h-10 w-10 place-items-center rounded-[10px] hover:bg-[rgba(72,148,255,0.08)]">
                <Icon name="bellnotify" size={19} />
                {/* the pulse is the UNREAD signal, so it only exists when there
                    is something unread — a bell that always pulses teaches the
                    reader to ignore it */}
                {unread > 0 && <span className="dot dot-live absolute right-2 top-2 bg-magenta text-magenta" />}
              </button>
              {notesOpen && (
                <NotificationsPanel
                  notes={notes}
                  onClose={() => setNotesOpen(false)}
                  onMarkAllRead={markAllRead}
                />
              )}
            </div>
            {/* The account controls, in the order they are reached for: the
                thing that pays you, the thing that identifies you, the way
                out. The avatar was previously inert — a picture of an account
                with nothing behind it — so it is now the link to Settings that
                everyone already tries to click. */}
            <Link
              href="/dashboard/refer"
              className="hidden items-center gap-1.5 rounded-[10px] border border-[#a86bff]/40 bg-[#a86bff]/12 px-3 py-1.5 text-[12px] font-bold text-[#c4a6ff] transition hover:border-[#a86bff]/70 hover:text-white md:flex"
            >
              <Icon name="handshake" size={14} tone="inherit" />
              Refer &amp; earn
            </Link>

            <Link href="/dashboard/settings"
                  title="Account settings"
                  className="flex items-center gap-2.5 rounded-[10px] px-1 py-1 transition hover:bg-[rgba(72,148,255,0.08)]">
              <span className="grid h-9 w-9 place-items-center rounded-full bg-[linear-gradient(150deg,#2f7eef,#8c3ae9)] text-[13px] font-extrabold text-white">
                {user.first.charAt(0).toUpperCase()}
              </span>
              <div className="hidden flex-col leading-tight sm:flex">
                <span className="text-[12.5px] font-bold text-white">{user.first}</span>
                <span className="text-[10.5px] text-tx-faint">{user.email}</span>
              </div>
            </Link>

            {/* A real POST to the server action, not a link: signing out mutates
                session state, and a GET that destroys a session is one prefetch
                away from logging people out on hover. */}
            <form action={logout}>
              <button type="submit" aria-label="Sign out" title="Sign out"
                      className="grid h-10 w-10 place-items-center rounded-[10px] text-tx-dim transition hover:bg-[rgba(255,90,90,0.1)] hover:text-red-300">
                <Icon name="logout" size={18} tone="inherit" />
              </button>
            </form>
          </div>
        </header>

        {/* `clip`, NOT `hidden`: clip contains the bleed without creating a
            scroll container, so the sticky rail and sticky headers inside keep
            working. Decorative glows and the rack's streams are free to spill
            past the content column and are cut only at the viewport. */}
        <main
          className={
            appFrame
              // `flex-none`, never `flex-1`: this column is a flex container, and
              // `flex: 1 1 0%` sets a flex-basis on the main axis that beats the
              // `height` .nx-appframe sets — the element silently keeps growing to
              // its content and the page scrolls anyway.
              ? "nx-appframe min-w-0 flex-none overflow-hidden"
              : "min-w-0 flex-1 px-3.5 pb-24 pt-4 [overflow-x:clip] sm:px-5 lg:px-6 lg:pb-8"
          }
        >
          {children}
          {/* Matrix renders HERE, as a sibling of the page rather than a fixed
              overlay measured from the viewport top. As an overlay it took its
              `top` from the header's height, which is only the header's BOTTOM
              edge when nothing sits above the header — and the sandbox banner
              does, so the panel started 72px down the viewport, which is inside
              the header, and clipped the account block. Letting the layout place
              it removes the arithmetic entirely and it still never unmounts,
              because this <main> doesn't. */}
          {matrixPanel}
        </main>
      </div>

      {/* mobile bottom tabs */}
      <nav className="fixed inset-x-0 bottom-0 z-40 flex h-[68px] items-stretch border-t border-rim-soft bg-side/95 backdrop-blur lg:hidden">
        {NAV.filter((n) => MOBILE_TABS.includes(n.href)).map((n) => {
          const active = n.href === activeHref;
          return (
            <Link key={n.href} href={n.href}
                  className={"flex flex-1 flex-col items-center justify-center gap-1 text-[10.5px] font-semibold " +
                             (active ? "text-white" : "text-tx-faint")}>
              <Icon name={n.icon} size={20} style={active ? undefined : { opacity: 0.75 }} />
              {n.label}
              {active && <span className="absolute bottom-0 h-[2px] w-10 rounded-full bg-[linear-gradient(90deg,#14c5e4,#8c3ae9)]" />}
            </Link>
          );
        })}
      </nav>
    </div>
  );
}

export function Shell({ children, user, badges = {}, notifications = [] }: {
  children: React.ReactNode; user: User; badges?: Badges; notifications?: Note[];
}) {
  // The composer lives at the SHELL level, exactly as it does in the portal
  // shell this one replaces. Two reasons it cannot move down into the mail
  // page: App Router keeps the shell mounted across in-portal navigation, so an
  // open (or minimized) composer and its in-progress draft survive moving
  // between pages; and MailClient calls `useCompose()` unconditionally, which
  // THROWS when no provider sits above it.
  //
  // That throw is not hypothetical — it took the whole inbox down. This shell
  // reproduced the portal shell's layout but not this provider, and the crash
  // is invisible until an account has a real, reachable mailbox: with none, the
  // mail page short-circuits to "No email plan yet" and never renders
  // MailClient at all. The first account with working mail gets an error
  // boundary instead of an inbox.
  // The SECOND provider this shell failed to reproduce, and the same bug
  // shape: `OpenTerminalButton` calls `useTerminalDock()`, which throws outside
  // a provider, so every RUNNING VPS detail page — and any game server whose
  // family check sent it down the VPS branch — rendered an error boundary
  // instead of a server. Invisible from the routes a smoke test walks, because
  // the button only mounts on a server's own page when it is running.
  //
  // MatrixPanel is the same omission a third time. It is mounted HERE rather
  // than by /dashboard/build's page because the App Router unmounts a page's
  // subtree on every route change, and Matrix's whole promise is that you can
  // leave a build running, go look at something else in the portal, and come
  // back to it still running. Mounted at the shell, its consoles and their
  // websockets outlive navigation. It renders nothing until the route is first
  // visited, so accounts that never open it pay nothing for it.
  return (
    <ComposeProvider>
      <TerminalDockProvider>
        <ShellInner user={user} badges={badges} notifications={notifications} matrixPanel={<MatrixPanel />}>
          {children}
        </ShellInner>
      </TerminalDockProvider>
    </ComposeProvider>
  );
}

