export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
  const user = await currentUser();
  if (!user) {
    // Where they were actually headed — critically, a marketing "Deploy"
    // button's full query string (game/plan/addon selection, see
    // lib/deploy-intent.ts), not just the bare path. Without this, EVERY
    // logged-out visit to any /dashboard/* route lost its destination on this
    // redirect, silently dropping the selection a Deploy click had just
    // encoded. `x-pathname`/`x-search` come from middleware.ts (Server
    // Components can't read the current URL directly); `safeNext` is the
    // same single-slash-absolute-path allowlist every other `?next=`
    // producer already uses (lib/safe-next.ts), so this is never a second
    // validation rule to keep in sync.
    const h = await headers();
    const dest = safeNext(`${h.get("x-pathname") ?? "/dashboard"}${h.get("x-search") ?? ""}`);
    redirect(dest ? `/login?next=${encodeURIComponent(dest)}` : "/login");
  }
  const imp = await impersonating();

  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
  // admins impersonating a customer) always pass so they can keep working. This
  // only covers the dashboard tree — /login and /admin have their own layouts.
  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
    const message = await getSetting("maintenance_message");
    return (
      <main
        style={{
          minHeight: "100vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: "1rem",
          padding: "2rem",
          textAlign: "center",
        }}
      >
        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
      </main>
    );
  }

  // Hide nav entries whose feature flag is disabled (secondary to the server-side
  // refusals in the order/create actions).
  const flags: Record<string, boolean> = {
    feature_game_servers: await getSettingBool("feature_game_servers", true),
    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
    feature_domains: await getSettingBool("feature_domains", true),
    feature_referrals: await getSettingBool("feature_referrals", true),
    // Off by default — hidden until publishing / the feature is live (see FEATURE_HREF).
    feature_website_builder: await getSettingBool("feature_website_builder", false),
    feature_calendar: await getSettingBool("feature_calendar", false),
  };
  const visibleNav: NavSection[] = nav
    .map((section) => ({
      ...section,
      items: section.items.filter((item) => {
        const flag = FEATURE_HREF[item.href];
        return !flag || flags[flag];
      }),
    }))
    .filter((section) => section.items.length > 0);

  const notifications = await db.notification.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "desc" },
    take: 15,
  });

  // Support badge: this customer's own tickets awaiting a staff reply
  // (their newly opened tickets + threads where they replied last). Fails soft.
  const supportAwaiting = await db.ticket
    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
    .catch(() => 0);
  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
    ...section,
    items: section.items.map((item) =>
      item.href === "/dashboard/support" && supportAwaiting > 0
        ? { ...item, badge: supportAwaiting }
        : item
    ),
  }));

  // Provide the display-currency context to the portal so browse/catalog prices
  // can localize. DISPLAY ONLY: wallet balances, invoices and any actual CHARGE
  // amount must stay in USD and are NOT routed through this — see the boundary
  // note in lib/currency.ts. Only components that explicitly opt in via
  // `useDisplayMoney()` convert; nothing here is auto-converted.
  const { currency: displayCurrency, rates: fxRates } = await resolveDisplayCurrency();

  return (
    <CurrencyProvider initialCurrency={displayCurrency} rates={fxRates}>
    {/* Rendered as a SIBLING before <Shell>, not passed as one of its
        children — Shell's own root (components/nx/Shell.tsx) renders its top
        navbar (search, currency, notifications, profile) ahead of whatever
        children it's given, so a child never sits above that bar no matter
        how early it's ordered among the other children. This is the same
        topmost slot SandboxBanner occupies in the root layout (above
        literally everything, app/layout.tsx) — moved out here (2026-09-22,
        real feedback) after it rendered below the email-verification banner
        AND below Shell's own top bar. */}
    {!imp && <PromoTrialPopup />}
    {/* Badges for the designed rail. `supportAwaiting` is already computed
        above for the portal shell's own nav; this reuses it rather than
        counting the same tickets a second time. */}
    {/* The Nexion shell, ported verbatim from the design sandbox. It takes the
        session user and nothing else — the nav is the designed twelve-item rail
        (lib/nx/nav.ts), not the portal's generated one.

        STILL TO PORT from components/portal/Shell: the notifications panel and
        the impersonation banner. Both are real features with no counterpart in
        the design yet; they are not lost, just not drawn here. Design them, then
        wire `notifications` / `impersonation` back in. */}
    <Shell
      user={{ first: user.name.split(" ")[0], email: user.email, balanceCents: user.balanceCents }}
      badges={{ "/dashboard/support": supportAwaiting }}
      notifications={notifications.map((n) => ({
        id: n.id,
        title: n.title,
        body: n.body,
        href: n.href,
        readAt: n.readAt ? n.readAt.toISOString() : null,
        createdAt: n.createdAt.toISOString(),
      }))}
    >
      {/* Impersonation goes FIRST and is never dismissible — an admin who
          forgets which account they are in is the expensive failure here. */}
      {imp && <ImpersonationBanner adminName={imp.admin.name} targetEmail={imp.target.email} />}
      {/* Unverified accounts browse the whole portal freely; only buying is
          gated (lib/email-verification.ts). The prompt lives here rather than at
          checkout so the customer meets the prerequisite while it is cheap to
          fix, instead of meeting it with a card in their hand. Hidden while an
          admin is impersonating: it is not the admin's address to confirm, and
          the resend button would mail the customer from inside someone else's
          session. */}
      {!imp && !isEmailVerified(user) && !isGrandfathered(user) && (
        <VerifyEmailBanner email={user.email} />
      )}
      {/* Admin broadcasts — dismissible per-user. Soft-fails to nothing so a
          broadcast query problem can never take down the portal. */}
      <AnnouncementBanner announcements={await activeAnnouncementsForUser().catch(() => [])} />
      {/* Fires the Meta/Google Purchase conversion when a freshly-paid order lands on
          any dashboard route (fulfil-checkout tags the redirect). No-op otherwise. */}
      <PurchaseTracker />
      {/* Fires the "signup" conversion once when a freshly-registered account lands
          here (register() redirects to ?signup=1). Strips the marker; no-op otherwise. */}
      <SignupTracker />
      {/* Kodely (or any future partner) deep link (?ref=kodely) -> a short-lived
          cookie so payAndDeploy/purchaseDomain can attribute the order without
          threading the param through every wizard step. */}
      <PartnerSourceCapture />
      {/* One-time "How did you hear about us?" survey. Only when the account has
          not answered yet (heardAboutUs is null) and NOT while an admin is
          impersonating — the admin must never answer the survey on the
          customer's behalf. The server action is itself guarded to write only
          when null, so this is a UI gate over an idempotent write. */}
      {!imp && user.heardAboutUs == null && <HeardAboutUsPrompt />}
      {/* Update announcements popup — shows unseen service updates one at a
          time. Fetches client-side (no SSR delay) and soft-fails to nothing. */}
      <AnnouncementPopup />
      {children}
    </Shell>
    </CurrencyProvider>
  );
}
import { NextRequest, NextResponse } from "next/server";

function hostList(envVar: string | undefined): string[] {
  return (envVar ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

// Every file actually committed under public/ -- logos, game art, flags,
// brand assets, blog images, docs, fonts. None of it is per-customer or
// sensitive; it's already served unauthenticated at the same path on the
// main site, so exposing it on the admin/staff hosts too doesn't defeat the
// isolation below (that's about app pages like /dashboard, not static
// files). Without this, every <img> under public/ 404s on the admin/staff
// hosts -- found live 2026-09-14 when the What's New announcement preview
// (game art, screenshots, the Nxeon logo) rendered as broken images in the
// admin panel while the identical page worked fine for customers.
const STATIC_ASSET_RE =
  /\.(?:png|jpe?g|gif|webp|svg|ico|mp4|webm|woff2?|css|json|txt|md|html)$/i;

/**
 * Reachable on every host regardless of portal mode: Next internals, the API
 * surface every portal's own client code calls (chat SSE, uploads, etc.),
 * the auth utility pages every login form links to, and static files under
 * public/. Everything else is scoped to exactly one portal below.
 */
function isUniversallyAllowed(pathname: string): boolean {
  return (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api/") ||
    pathname === "/favicon.ico" ||
    pathname.startsWith("/.well-known/") ||
    pathname === "/forgot-password" ||
    pathname === "/reset-password" ||
    // Both portal layouts redirect a staff/admin account without 2FA here to
    // enroll (enforce_staff_2fa) -- account security settings aren't
    // customer-specific, and blocking this would stand between a legitimate
    // staff member and the one page that lets them satisfy the requirement.
    pathname === "/dashboard/settings" ||
    STATIC_ASSET_RE.test(pathname)
  );
}

/**
 * Confines the admin/staff hostnames to exactly their own portal.
 *
 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
 * direction -- /admin and /staff 404 on any host that isn't their own
 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
 * admin/staff hostnames proxy to the exact same Next.js backend as the main
 * site, so /dashboard, /login, /register, and every marketing page were
 * equally reachable there too -- confirmed live 2026-09-02, a customer's full
 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
 * Not a data leak (they only ever saw their own account), but it defeats the
 * point of a separate, minimal, operations-only surface, and reduces
 * whatever "hard to guess" value the admin subdomain has by leaving it fully
 * browsable/indexable as a second copy of the public site.
 *
 * Together with the two layouts' existing checks this makes the mapping
 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
 * host <-> everything except /admin and /staff.
 */
export function middleware(req: NextRequest) {
  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
  const { pathname } = req.nextUrl;

  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);

  // An admin impersonating a customer (lib/auth.ts's setImpersonation) needs to
  // browse the FULL customer app -- /dashboard, /checkout, etc. -- from their own
  // admin host, since impersonation swaps identity without changing host. Only
  // ADMIN can ever hold this cookie (EMPLOYEE/staff can never impersonate -- see
  // setImpersonation's own role check), so this only ever loosens the admin
  // host. We only check the cookie's PRESENCE here, not its signature/validity
  // -- that's exactly as strong as this gate needs to be: a forged or expired
  // token still gets fully re-verified by impersonating()/currentUser() at the
  // page/action layer, so a bad cookie here just falls back to "no session",
  // never to unauthorized access.
  const impCookieName = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
  const isImpersonating = isAdminHost && req.cookies.has(impCookieName);

  if ((isAdminHost || isStaffHost) && !isImpersonating) {
    const ownPrefix = isAdminHost ? "/admin" : "/staff";
    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";

    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix)) {
      // The shared /login page (and any stray redirect to it -- logout()
      // always sends there, regardless of who's logging out) lands on this
      // host's own dedicated login instead of 404ing a signed-out visitor.
      if (pathname === "/login") {
        const url = req.nextUrl.clone();
        url.pathname = ownLogin;
        return NextResponse.redirect(url);
      }
      // The bare root -- where someone typing/bookmarking just the hostname
      // lands -- goes to the portal itself rather than 404ing. The admin
      // vhost happens to have its own nginx-level `location = / return 302
      // /admin` that already covered this there (confirmed live), but the
      // staff vhost has no equivalent, so its root 404'd under this same
      // isolation logic. Handling it here covers both hosts the same way
      // regardless of nginx config: an authenticated visit shows the portal,
      // an unauthenticated one gets bounced on to ownLogin by the layout's
      // own existing redirect -- no new auth logic needed either way.
      if (pathname === "/") {
        const url = req.nextUrl.clone();
        url.pathname = ownPrefix;
        return NextResponse.redirect(url);
      }
      return new NextResponse("Not found.", { status: 404 });
    }
  }

  // Server Components have no built-in way to read the current pathname --
  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
  // their own /login sub-route (public, no Shell, no auth redirect) without
  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
  // downstream Server Component actually sees it.
  const requestHeaders = new Headers(req.headers);
  requestHeaders.set("x-pathname", pathname);
  // Same reasoning, for the query string: app/dashboard/layout.tsx's
  // logged-out redirect needs the FULL URL a marketing "Deploy" button sent a
  // visitor to (e.g. `/dashboard/deploy?product=game&family=valheim&tier=...`,
  // see lib/deploy-intent.ts) so it can send them to `/login?next=<that URL>`
  // instead of a bare `/login` that drops the selection the customer already
  // made. Kept separate from `x-pathname` rather than folded into it so every
  // existing exact-pathname comparison (`pathname === "/admin/login"`, etc.)
  // keeps working unchanged.
  requestHeaders.set("x-search", req.nextUrl.search);
  return NextResponse.next({ request: { headers: requestHeaders } });
}

