const money = (cents: number) =>
  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/* One bucket per audit action, so the feed reads as icons rather than dots. */
function actIcon(action: string): { icon: string; tone: "" | "c" | "v" | "m" } {
  if (action.startsWith("wallet") || action.includes("invoice") || action.includes("topup")) return { icon: "card", tone: "m" };
  if (action.includes("create") || action.includes("provision")) return { icon: "cloudup", tone: "c" };
  if (action.includes("restore") || action.includes("snapshot") || action.includes("backup")) return { icon: "refresh", tone: "" };
  if (action.startsWith("domain")) return { icon: "nodes", tone: "c" };
  if (action.includes("delete") || action.includes("suspend")) return { icon: "warntriangle", tone: "m" };
  if (action.includes("build") || action.includes("matrix")) return { icon: "terminal", tone: "v" };
  return { icon: "activity", tone: "v" };
}

function nxStatus(status: string): Row["status"] {
  if (status === "RUNNING") return "Online";
  if (["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(status)) return "Maintenance";
  return "Offline";
}

/* "Jan 12, 2026" + "in 45 days", the two lines the Renewal column shows. */
function renewal(expiresAt: Date | null): { renew: string; inDays: string } {
  if (!expiresAt) return { renew: "—", inDays: "no term" };
  const days = Math.round((expiresAt.getTime() - Date.now()) / 86_400_000);
  return {
    renew: expiresAt.toLocaleDateString("en-US", { month: "short", day: "2-digit", year: "numeric" }),
    inDays: days < 0 ? `${-days} days ago` : days === 0 ? "today" : `in ${days} day${days === 1 ? "" : "s"}`,
  };
}

function ago(d: Date): string {
  const m = Math.floor((Date.now() - d.getTime()) / 60_000);
  if (m < 1) return "just now";
  if (m < 60) return `${m} min ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h} hour${h === 1 ? "" : "s"} ago`;
  const dd = Math.floor(h / 24);
  return dd === 1 ? "Yesterday" : `${dd} days ago`;
}

export default async function DashboardPage() {
  const user = await requireUser();
  const monthAgo = new Date(Date.now() - 30 * 86_400_000);

  const [servers, hostingCount, hasFree, auditLogs, openTickets, newThisMonth, plans, gamePlans, hostingPlans, emailPlans] =
    await Promise.all([
