    regionOnline.set(n.region, (regionOnline.get(n.region) ?? true) && reachable);
  }
  const network: NetRegion[] = [...regionOnline.entries()].map(([region, online]) => ({
    key: region,
    name: customerRegionLabel(region),
    lon: REGION_COORDS[region]?.lon ?? 0,
