/* Support, on the concept's structure — Tickets / Live Chat / Help Center /
 * Service Status.
 *
 * The concept's stat strip also carries "99.8% Customer Satisfaction" — that
 * one has no backing data anywhere in this platform (no CSAT survey exists),
 * so it stays out. Its neighbour, "Avg response time", DOES now have a real
 * source: the gap between a ticket's own `createdAt` (the opening message)
 * and the first staff reply is a real, measured duration, not a marketing
 * SLA — so it is computed below from this customer's own ticket history
 * instead of being either fabricated or dropped. `null` ("not enough data
 * yet") when none of their tickets have a staff reply yet.
 *
 * What else IS measured: how many of your tickets are open, how many are
 * waiting on you, and how many closed recently (TicketStatus); the real Help
 * Center content (lib/help.ts, grouped published BlogPosts — the same data
 * /help runs on); and the real platform health/incident history
 * (lib/monitoring.ts — the same data the public /status page runs on).
 */
export default async function SupportPage({
  searchParams,
}: {
  searchParams: Promise<{ ticket?: string; dm?: string }>;
}) {
  const user = await requireUser();
  const { ticket: initialTicketId, dm: initialDmId } = await searchParams;
  const monthAgo = new Date(Date.now() - 30 * 86_400_000);

  const [tickets, closedRecently, firstStaffReplies, helpData, health, uptime, incidents] = await Promise.all([
    db.ticket.findMany({
      where: { userId: user.id },
      select: {
        id: true, subject: true, status: true, priority: true,
        createdAt: true, updatedAt: true,
      },
      orderBy: { updatedAt: "desc" },
      take: 40,
    }),
    db.ticket.count({
      where: { userId: user.id, status: "CLOSED", updatedAt: { gte: monthAgo } },
    }),
    db.ticketMessage.groupBy({
      by: ["ticketId"],
      where: { ticket: { userId: user.id }, isStaff: true },
      _min: { createdAt: true },
    }),
    getHelpData(),
    getHealth(),
    uptimeSummary(),
    listIncidents(),
  ]);

  /* Staff-initiated direct messages (StaffDm) — a separate, much smaller
     inbox from the ticket list above (see prisma/schema.prisma's StaffDm
     doc comment for why it's not just another Ticket row). Unlike the
     ticket list's two-step preview fetch, a nested `take: 1` here is fine:
     this is one customer's own handful of DM threads, not a global queue. */
  const staffDmRows = (await dmDb.staffDm.findMany({
    where: { userId: user.id },
    select: {
      id: true,
      subject: true,
      status: true,
      updatedAt: true,
      unreadForCustomer: true,
      messages: { orderBy: { createdAt: "desc" }, take: 1, select: { body: true, isStaff: true } },
    },
    orderBy: { updatedAt: "desc" },
    take: 40,
  })) as {
    id: string;
    subject: string;
    status: string;
    updatedAt: Date;
    unreadForCustomer: boolean;
    messages: { body: string; isStaff: boolean }[];
  }[];
  const dms: DmSummary[] = staffDmRows.map((dm) => ({
    id: dm.id,
    subject: dm.subject,
    status: dm.status,
    updatedAt: dm.updatedAt.toISOString(),
    unreadForCustomer: dm.unreadForCustomer,
    preview: (dm.messages[0]?.body ?? "").replace(/\s+/g, " ").slice(0, 120),
  }));

  /* The latest message per ticket, for the list preview. This used to ride
     along as a nested `messages: { orderBy, take: 1 }` select on the ticket
     query above — but Prisma's default ("query") relation strategy has no
     SQL-level LIMIT per parent for a nested to-many `take`: it fetches EVERY
     TicketMessage row (full `body` text included) for all 40 tickets via a
     single `ticketId IN (...)` query, orders it, and only then discards all
     but the newest per ticket. For a long-running ticket thread that is a lot
     of wasted body bytes pulled over the wire and thrown away. Instead: get
     just the max(createdAt) per ticket (a cheap aggregate, no body), then
     fetch exactly those rows — at most one per ticket. */
  const ticketIds = tickets.map((t) => t.id);
  const lastMessageMeta = ticketIds.length
    ? await db.ticketMessage.groupBy({
        by: ["ticketId"],
        where: { ticketId: { in: ticketIds } },
        _max: { createdAt: true },
      })
    : [];
  const lastMessages = lastMessageMeta.length
    ? await db.ticketMessage.findMany({
        where: {
          OR: lastMessageMeta
            .filter((m) => m._max.createdAt)
            .map((m) => ({ ticketId: m.ticketId, createdAt: m._max.createdAt! })),
        },
        select: { ticketId: true, body: true, isStaff: true, createdAt: true },
      })
    : [];
  const lastMessageByTicket = new Map(lastMessages.map((m) => [m.ticketId, m]));

  const rows = tickets.map((t) => {
    const last = lastMessageByTicket.get(t.id);
    return {
      id: t.id,
      subject: t.subject,
      status: t.status,
      priority: t.priority,
      updated: t.updatedAt.toISOString(),
      /* The last message, trimmed for the list. Staff or customer is marked so a
         reader can tell at a glance whose move it is. */
      preview: last?.body.replace(/\s+/g, " ").slice(0, 120) ?? "",
      lastFromStaff: last?.isStaff ?? false,
    };
  });

  const firstReplyByTicket = new Map(firstStaffReplies.map((r) => [r.ticketId, r._min.createdAt]));
  const responseMinutes: number[] = [];
  for (const t of tickets) {
    const firstStaffAt = firstReplyByTicket.get(t.id);
    if (firstStaffAt) responseMinutes.push((firstStaffAt.getTime() - t.createdAt.getTime()) / 60000);
  }
  const avgResponseMin = responseMinutes.length > 0
    ? Math.round(responseMinutes.reduce((a, b) => a + b, 0) / responseMinutes.length)
    : null;

  const help = helpData.sections.map((s) => ({
    name: s.category.name,
    slug: s.category.slug,
    emoji: s.category.emoji,
    blurb: s.category.blurb,
    count: s.posts.length,
  }));

  /* Combine open + resolved into one recent-incidents list, newest first,
     capped small — this is a support tab, not the full status page. */
  const recentIncidents = [...incidents.open, ...incidents.resolved]
    .sort((a, b) => new Date(b.startedAt).getTime() - new Date(a.startedAt).getTime())
    .slice(0, 6);

  return (
    <SupportView
      viewer={{ name: user.name ?? null, email: user.email ?? null }}
      viewerId={user.id}
      tickets={rows}
      open={rows.filter((t) => t.status !== "CLOSED").length}
      /* "Waiting for you" is ANSWERED — staff replied and the ball is in the
         customer's court. That is the state worth surfacing; it is the one they
         can act on. */
      waitingOnYou={rows.filter((t) => t.status === "ANSWERED").length}
      closedRecently={closedRecently}
      avgResponseMin={avgResponseMin}
      initialTicketId={initialTicketId ?? null}
      dms={dms}
      initialDmId={initialDmId ?? null}
      help={help}
      helpTotal={helpData.total}
      status={{
        overall: overallStatus(health),
        components: HEALTH_COMPONENTS.map((key) => ({
          key,
          label: COMPONENT_LABELS[key],
          status: health[key].status,
          uptimePct: uptime[key].pct,
        })),
        incidents: recentIncidents.map((inc) => ({
          id: inc.id,
          title: inc.title,
          body: inc.body,
          severity: inc.severity,
