"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { z } from "zod";
import { db } from "./db";
import { requireUser } from "./auth";
import { hasAreaAccess } from "./staff-grants";
import { writeTicketReply, createTicketCore } from "./reply-core";
import { mirrorNewTicketToDiscord, mirrorTicketReplyToDiscord, setDiscordThreadArchived } from "./discord-bridge";
import { validateTicketAttachmentBytes, MAX_TICKET_ATTACHMENT_BYTES } from "./ticket-attachment";

/**
 * SUPPORT-ROLE ENFORCEMENT (2026-07-27 admin audit).
 *
 * `lib/rbac.ts` grants the `support` area to SUPPORT and ADMIN, `/admin/support`
 * and `/admin/support/[id]` both gate on `requireArea("support")`, and the admin
 * layout renders the desk in a SUPPORT agent's sidebar. Every WRITE behind those
 * pages, however, still required ADMIN:
 *
 *   - `setTicketPriority` called `requireAdmin()`. `PrioritySelect` does not
 *     catch, so a SUPPORT agent picked "Urgent", the throw vanished into an
 *     unhandled transition, and the `<select>` (uncontrolled, `defaultValue`)
 *     kept showing the new value. The control reported success and did nothing.
 *   - `setTicketStatus` and `replyTicket` applied the CUSTOMER ownership test
 *     (`ticket.userId !== user.id && role !== "ADMIN"`), so a SUPPORT agent could
 *     neither close nor answer a ticket that was not their own — i.e. any ticket.
 *
 * So the entire job of the SUPPORT role was a read-only page with three controls
 * that silently refused. `lib/actions-chat.ts` — the other half of the same area —
 * has always gated correctly on `requireArea("support")`; the ticket desk simply
 * was never updated when RBAC landed. These now use the same rule. No role gains
 * anything `lib/rbac.ts` did not already declare, and CUSTOMER is unaffected:
 * a customer still reaches only their own ticket.
 */
/**
 * The session behind a ticket action, plus whether they are support staff.
 *
 * Named `require*` deliberately. `test/auth-lockouts.test.ts` enforces that every
 * export of a "use server" file — each of which is a network-callable endpoint
 * anyone can POST to — calls a recognised guard INSIDE the function, and it
 * recognises guards by the `require*`/`owned*`/`assert*`/`resolve*` convention.
 * This helper was `ticketActor`, which guarded correctly but did not LOOK like a
 * guard, so the tripwire reported three genuinely-safe endpoints as unguarded.
 *
 * The fix was the name, not the rule: widening the rule to accept arbitrary
 * helper names would let a future function that guards nothing pass the same
 * check. A guard should be recognisable as one.
 */
async function requireTicketActor(): Promise<{ id: string; isSupportStaff: boolean }> {
  const user = await requireUser();
  return { id: user.id, isSupportStaff: await hasAreaAccess(user, "supportTickets") };
}

export async function createTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const parsed = z
    .object({
      subject: z.string().min(3).max(150),
      body: z.string().min(5).max(10000),
      priority: z.enum(["LOW", "NORMAL", "HIGH", "URGENT"]).default("NORMAL"),
    })
    .safeParse({
      subject: formData.get("subject"),
      body: formData.get("body"),
      priority: formData.get("priority") ?? "NORMAL",
    });
  if (!parsed.success) return { error: "Subject (3+) and message (5+) required." };

  const ticket = await createTicketCore({
    userId: user.id,
    subject: parsed.data.subject,
    body: parsed.data.body,
    priority: parsed.data.priority,
  });
  // Discord bridge (Phase 1 mirror): best-effort, never blocks ticket creation
  // or the redirect below — see lib/discord-bridge.ts's top-of-file comment.
  await mirrorNewTicketToDiscord(ticket.ticketId);
  redirect(`/dashboard/support/${ticket.ticketId}`);
}

/** Sending a screenshot plus a few follow-up crops in one go is normal; sending
 *  fifty is not what the picker/paste flow below is for. */
const MAX_ATTACHMENTS_PER_REPLY = 6;

export async function replyTicket(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireTicketActor();
  const ticketId = String(formData.get("ticketId") ?? "");
  const body = String(formData.get("body") ?? "").trim();

  // Ownership guard, kept directly in this "use server" boundary — every
  // export of this file is a public network endpoint (see this file's
  // top-of-file comment on the exact RBAC bug that made that non-obvious).
  // `writeTicketReply` (lib/reply-core.ts) re-checks this same thing before
  // writing, so this is deliberate defense-in-depth, not the only place it's
  // enforced — but a reviewer of THIS file should still see proof a customer
  // can only reply to their own ticket without having to trust an opaque
  // helper elsewhere.
  const ticketOwner = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticketOwner) return { error: "Ticket not found." };
  if (ticketOwner.userId !== user.id && !user.isSupportStaff) return { error: "Forbidden." };

  // Zero or more attachments (paste-multiple-images, or picking several files
  // at once). The same ownership guard above already covers who may attach —
  // a customer can only ever reach here for their own ticket, staff for any
  // ticket they can open. `formData.getAll` is how multiple entries under the
  // same `<input name="file" multiple>` arrive.
  const rawFiles = formData.getAll("file").filter((f): f is File => f instanceof File && f.size > 0);
  if (rawFiles.length > MAX_ATTACHMENTS_PER_REPLY) {
    return { error: `Attach at most ${MAX_ATTACHMENTS_PER_REPLY} files per message.` };
  }
  const attachments: { mime: string; name: string; size: number; data: Buffer }[] = [];
  for (const file of rawFiles) {
    if (file.size > MAX_TICKET_ATTACHMENT_BYTES) {
      return { error: `"${file.name}" is larger than 10 MB.` };
    }
    const bytes = Buffer.from(await file.arrayBuffer());
    const check = validateTicketAttachmentBytes(bytes, file.type, file.name);
    if (!check.ok) return { error: `"${file.name}": ${check.error}` };
    attachments.push({ mime: check.mime, name: file.name.slice(0, 200) || "attachment", size: check.bytes.length, data: check.bytes });
  }

  // The first attachment (if any) rides on the same message as the typed
  // body, exactly as a single-attachment reply always has. Any additional
  // ones are written directly here as their own attachment-only messages
  // from the same author, right behind it — `writeTicketReply` is the one
  // shared write path for tickets, live chat AND the Discord bridge, and it
  // fires one notification/email per call, so looping it per image would
  // spam staff with N notifications for what the customer experienced as a
  // single send. TicketThreadPanel re-clusters consecutive same-author sends
  // back into one visual bubble with an image grid.
  const result = await writeTicketReply({
    actorId: user.id,
    actorIsSupportStaff: user.isSupportStaff,
    ticketId,
    body,
    attachment: attachments[0],
  });
  if (result.error) return { error: result.error };

  const extra = attachments.slice(1);
  if (extra.length) {
    await db.ticketMessage.createMany({
      data: extra.map((a) => ({
        ticketId,
        body: "",
        authorId: user.id,
        isStaff: Boolean(result.isStaff),
        attachmentData: new Uint8Array(a.data),
        attachmentMime: a.mime,
        attachmentName: a.name,
        attachmentSize: a.size,
      })),
    });
  }

  // Discord bridge (Phase 1 mirror): best-effort. This reply was written from
  // the web dashboard, never from Discord (Discord-originated replies go
  // through app/api/webhooks/discord/route.ts, which calls writeTicketReply
  // directly and does NOT mirror — otherwise a Discord reply would echo right
  // back into the same Discord thread it came from).
  const attachNote = attachments.length
    ? attachments.length === 1
      ? `📎 ${attachments[0].name} (attachment — view in the dashboard)`
      : `📎 ${attachments.length} attachments (view in the dashboard)`
    : undefined;
  const mirrorBody = body || attachNote || "";
  await mirrorTicketReplyToDiscord(ticketId, mirrorBody, Boolean(result.isStaff));

  revalidatePath(`/dashboard/support/${ticketId}`);
  revalidatePath(`/admin/support/${ticketId}`);
  return {};
}

/**
 * "Is typing" signal — deliberately in-memory, never persisted. Every real
 * chat product treats typing indicators as throwaway state (Slack, Discord,
 * iMessage never write one to a database); a DB round trip for something
 * that expires in 4 seconds would be pure churn. This assumes a single Node
 * process, which is what this app runs as — if that ever changes, this map
 * would need to move to a shared store, but it does not need to yet.
 */
const typingPings = new Map<string, { staffAt: number; customerAt: number }>();
const TYPING_TTL_MS = 4000;

function sweepTypingPings() {
  const cutoff = Date.now() - 5 * 60_000;
  for (const [id, v] of typingPings) {
    if (v.staffAt < cutoff && v.customerAt < cutoff) typingPings.delete(id);
  }
}

/** Called (throttled, client-side) on every keystroke in a ticket's reply box. */
export async function pingTyping(ticketId: string): Promise<void> {
  const user = await requireTicketActor();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket) return;
  if (ticket.userId !== user.id && !user.isSupportStaff) return;
  const isStaff = user.isSupportStaff && ticket.userId !== user.id;
  sweepTypingPings();
  const prev = typingPings.get(ticketId) ?? { staffAt: 0, customerAt: 0 };
  typingPings.set(ticketId, isStaff ? { ...prev, staffAt: Date.now() } : { ...prev, customerAt: Date.now() });
}

/** Whether the OTHER party (relative to whoever's asking) is typing right now. */
export async function getTypingStatus(ticketId: string): Promise<{ typing: boolean }> {
  const user = await requireTicketActor();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket) return { typing: false };
  if (ticket.userId !== user.id && !user.isSupportStaff) return { typing: false };
  const viewerIsStaff = user.isSupportStaff && ticket.userId !== user.id;
  const ping = typingPings.get(ticketId);
  if (!ping) return { typing: false };
  const at = viewerIsStaff ? ping.customerAt : ping.staffAt;
  return { typing: Date.now() - at < TYPING_TTL_MS };
}

/**
 * A TypeScript parameter type is a compile-time comment on a network endpoint.
 *
 * Every export of this file is POST-able with any JSON the caller likes, so the
 * `"OPEN" | "CLOSED"` annotations below constrained the components and nothing
 * else. `TicketStatus` also contains ANSWERED and CUSTOMER_REPLY — both writable
 * here — so a customer could stamp their own ticket ANSWERED and drop it out of
 * the support queue's "needs a reply" view without anyone having replied. Values
 * outside the enum reached Prisma and threw, which surfaces as a server error
 * page rather than a message. Both are fixed by validating at the boundary.
 */
const TICKET_STATUS_CHOICES = ["OPEN", "CLOSED"] as const;
const TICKET_PRIORITY_CHOICES = ["LOW", "NORMAL", "HIGH", "URGENT"] as const;

export async function setTicketStatus(ticketId: string, status: "OPEN" | "CLOSED") {
  const user = await requireTicketActor();
  if (!TICKET_STATUS_CHOICES.includes(status as (typeof TICKET_STATUS_CHOICES)[number])) {
    throw new Error("A ticket can only be reopened or closed from here.");
  }
  const ticket = await db.ticket.findUnique({ where: { id: ticketId } });
  if (!ticket) throw new Error("Not found");
  if (ticket.userId !== user.id && !user.isSupportStaff) throw new Error("Forbidden");
  await db.ticket.update({ where: { id: ticketId }, data: { status } });
  // Best-effort, never blocks the status change itself.
  void setDiscordThreadArchived("ticket", (ticket as any).discordThreadId, status === "CLOSED");
  revalidatePath(`/dashboard/support`);
  revalidatePath(`/dashboard/support/${ticketId}`);
  revalidatePath(`/admin/support`);
  revalidatePath(`/admin/support/${ticketId}`);
}

export async function setTicketPriority(ticketId: string, priority: "LOW" | "NORMAL" | "HIGH" | "URGENT") {
  const user = await requireTicketActor();
  // Triage is a staff-only judgement — a customer must not be able to promote
  // their own ticket to URGENT — but it IS the support desk's job.
  if (!user.isSupportStaff) throw new Error("Forbidden");
  if (!TICKET_PRIORITY_CHOICES.includes(priority as (typeof TICKET_PRIORITY_CHOICES)[number])) {
    throw new Error("Priority must be one of: LOW, NORMAL, HIGH, URGENT.");
  }
  await db.ticket.update({ where: { id: ticketId }, data: { priority } });
  revalidatePath(`/admin/support`);
  revalidatePath(`/admin/support/${ticketId}`);
}

/** How long after sending a message its author may still edit it. */
const EDIT_WINDOW_MS = 5 * 60_000;

/**
 * Edit the body of your own message, within 5 minutes of sending it, while the
 * ticket is open. The 5-minute window is enforced HERE against `createdAt` —
 * never trust a client-side countdown, which only controls whether the "Edit"
 * affordance is shown. `editedAt` is set so both the admin and customer UI can
 * render an "(edited)" label — an edit is a transparency signal both parties
 * see, unlike the read receipts below which are staff-facing only.
 */
export async function editTicketMessage(messageId: string, newBody: string): Promise<{ error?: string }> {
  const user = await requireUser();
  const body = newBody.trim();
  if (body.length < 2 || body.length > 10000) return { error: "Message must be between 2 and 10,000 characters." };

  const message = await db.ticketMessage.findUnique({
    where: { id: messageId },
    include: { ticket: { select: { id: true, status: true } } },
  });
  if (!message) return { error: "Message not found." };
  if (message.authorId !== user.id) return { error: "You can only edit your own messages." };
  if (message.ticket.status === "CLOSED") return { error: "This ticket is closed." };
  if (Date.now() - message.createdAt.getTime() >= EDIT_WINDOW_MS) {
    return { error: "You can only edit a message within 5 minutes of sending it." };
  }

  await db.ticketMessage.update({ where: { id: messageId }, data: { body, editedAt: new Date() } });
  revalidatePath(`/dashboard/support/${message.ticket.id}`);
  revalidatePath(`/admin/support/${message.ticket.id}`);
  return {};
}

/**
 * Stamp `readAt` on every unread STAFF message in this ticket — called once
 * from app/dashboard/support/[id]/page.tsx when the CUSTOMER who owns the
 * ticket views it. Deliberately one-directional: there is no equivalent call
 * for staff viewing a customer's messages, per the explicit design ("read
 * receipts from customers, but they dont get them from us") — staff sees when
 * the customer has read a staff reply; the customer never sees a receipt at all.
 */
export async function markTicketMessagesRead(ticketId: string): Promise<void> {
  const user = await requireUser();
  const ticket = await db.ticket.findUnique({ where: { id: ticketId }, select: { userId: true } });
  if (!ticket || ticket.userId !== user.id) return; // silently a no-op for anyone but the owning customer
  await db.ticketMessage.updateMany({
    where: { ticketId, isStaff: true, readAt: null },
    data: { readAt: new Date() },
  });
}

export type TicketThreadMessage = {
  id: string;
  body: string;
  isStaff: boolean;
  authorId: string;
  authorName: string;
  createdAt: string;
  editedAt: string | null;
  attachmentMime: string | null;
  attachmentName: string | null;
  attachmentSize: number;
};
export type TicketThread = {
  id: string;
  subject: string;
  status: string;
  priority: string;
  createdAt: string;
  messages: TicketThreadMessage[];
};

/**
 * One ticket's full thread, for the customer Support page's in-page ticket
 * view (components/nx/SupportView.tsx) — the list used to `<Link>` out to
 * app/dashboard/support/[id]/page.tsx, a full navigation, to show exactly
 * this. That page is now a thin redirect into `?ticket=` on the same page;
 * this is the read path both the initial deep-link load and every click
 * from the inline list call, so there is exactly one way a customer's own
 * ticket thread gets fetched.
 *
 * Same ownership rule as the rest of this file: the ticket's own customer,
 * or an admin. Also stamps read receipts, same as the page it replaces.
 */
export async function getTicketThread(ticketId: string): Promise<TicketThread | { error: string }> {
  const user = await requireUser();
  const ticket = await db.ticket.findUnique({
    where: { id: ticketId },
    include: {
      messages: {
        orderBy: { createdAt: "asc" },
        include: { author: { select: { name: true } } },
      },
    },
  });
  if (!ticket || (ticket.userId !== user.id && user.role !== "ADMIN")) return { error: "not_found" };

  await markTicketMessagesRead(ticket.id);

  return {
    id: ticket.id,
    subject: ticket.subject,
    status: ticket.status,
    priority: ticket.priority,
    createdAt: ticket.createdAt.toISOString(),
    messages: ticket.messages.map((m) => ({
      id: m.id,
      body: m.body,
      isStaff: m.isStaff,
      authorId: m.authorId,
      authorName: m.author.name ?? (m.isStaff ? "Nxeon staff" : "You"),
      createdAt: m.createdAt.toISOString(),
      editedAt: m.editedAt ? m.editedAt.toISOString() : null,
      attachmentMime: m.attachmentMime,
      attachmentName: m.attachmentName,
      attachmentSize: m.attachmentSize ?? 0,
    })),
  };
}

import "server-only";
import { z } from "zod";
import { db } from "./db";
import { maybeSendTicketReplyEmail } from "./ticket-reply-email";

/**
 * Shared reply-writing core for support tickets and live chat, extracted from
 * lib/actions-support.ts's `replyTicket` and lib/actions-chat.ts's
 * `replyToConversation` so there is exactly ONE code path that writes a
 * reply, regardless of which surface triggers it: the existing "use server"
 * actions behind /dashboard/support and /admin/chat, or the new Discord
 * bridge webhook (app/api/webhooks/discord/route.ts).
 *
 * SECURITY — READ THIS BEFORE CALLING EITHER FUNCTION BELOW.
 *
 * Neither function performs ANY authorization check. That is deliberate, not
 * an oversight: `lib/actions-support.ts`'s own top-of-file comment documents a
 * real, previously-shipped RBAC bug in this exact reply path (a SUPPORT agent
 * could silently neither answer nor close a ticket that wasn't their own), so
 * this extraction is surgical — the DB-write body moved here VERBATIM, auth
 * stayed put. Every existing caller still does its own guard before calling
 * in:
 *   - `replyTicket` (lib/actions-support.ts) calls `requireTicketActor()` first.
 *   - `replyToConversation`/`replyWithAttachment` (lib/actions-chat.ts) call
 *     `requireArea("support")` first.
 *   - The Discord webhook route's "auth" is Discord's own Ed25519
 *     interaction-signature verification (lib/discord.ts's
 *     `verifyDiscordSignature`) PLUS `lib/discord-bridge.ts`'s
 *     `resolveDiscordReplyActor`, which resolves the real Discord user who
 *     submitted the reply (via `interaction.member.user.id`) to a Nxeon
 *     `User.discordUserId` link and re-checks that account still has support
 *     access — see that file's top-of-file comment for the full design
 *     (real per-person linking via OAuth, no fallback to a single shared
 *     identity).
 *
 * Do NOT add a new caller of `writeTicketReply`/`writeChatReply` without first
 * adding its own auth check — these functions will happily write a reply
 * attributed to whatever actorId/staffId they're given.
 */

/** Write a ticket reply. Mirrors `replyTicket`'s exact prior DB-write body. */
export async function writeTicketReply(args: {
  /** The id of the user the message is authored as (TicketMessage.authorId). */
  actorId: string;
  /** Whether the calling actor is support staff (before the same-ticket-owner override below). */
  actorIsSupportStaff: boolean;
  ticketId: string;
  body: string;
  /** Optional single attachment (image or document) — see lib/ticket-attachment.ts. */
  attachment?: { mime: string; name: string; size: number; data: Buffer };
}): Promise<{ error?: string; isStaff?: boolean; ticketUserId?: string; subject?: string }> {
  const body = args.body.trim();
  // A message with an attachment and no caption is allowed (mirrors the chat
  // widget's image-only messages), so the length floor only applies when there
  // is no attachment to carry the message on its own.
  if (!args.attachment && (body.length < 2 || body.length > 10000)) return { error: "Message too short." };
  if (body.length > 10000) return { error: "Message is too long." };

  const ticket = await db.ticket.findUnique({ where: { id: args.ticketId } });
  if (!ticket) return { error: "Ticket not found." };
  // A staff member replying to their OWN ticket (as its customer) is not a
  // "staff reply" — exactly the same override the original action applied.
  const isStaff = args.actorIsSupportStaff && ticket.userId !== args.actorId;
  if (ticket.userId !== args.actorId && !args.actorIsSupportStaff) return { error: "Forbidden." };

  await db.$transaction([
    db.ticketMessage.create({
      data: {
        ticketId: args.ticketId,
        body,
        authorId: args.actorId,
        isStaff,
        ...(args.attachment
          ? {
              attachmentData: new Uint8Array(args.attachment.data),
              attachmentMime: args.attachment.mime,
              attachmentName: args.attachment.name,
              attachmentSize: args.attachment.size,
            }
          : {}),
      },
    }),
    db.ticket.update({
      where: { id: args.ticketId },
      data: { status: isStaff ? "ANSWERED" : "CUSTOMER_REPLY" },
    }),
  ]);

  if (isStaff) {
    await db.notification.create({
      data: {
        userId: ticket.userId,
        title: `Support replied: ${ticket.subject}`,
        href: `/dashboard/support/${args.ticketId}`,
      },
    });
    // Also EMAIL the customer the staff reply — an in-app bell alone is easy to
    // miss. Best-effort: a mail failure must never fail the reply itself.
    // Rate-governed (coalesce window + daily cap) — see lib/ticket-reply-email.ts.
    try {
      await maybeSendTicketReplyEmail({
        ticketId: args.ticketId,
        ticketUserId: ticket.userId,
        ticketSubject: ticket.subject,
        replyBody: body,
      });
    } catch (e) {
      console.error("[support] staff-reply email failed (non-fatal)", e);
    }
  } else {
    const admins = await db.user.findMany({ where: { role: "ADMIN" } });
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `Ticket reply: ${ticket.subject}`,
        href: `/admin/support/${args.ticketId}`,
      })),
    });
  }

  return { isStaff, ticketUserId: ticket.userId, subject: ticket.subject };
}

/** Write a chat reply. Mirrors `replyToConversation`'s exact prior DB-write body. */
export async function writeChatReply(args: {
  conversationId: string;
  body: string;
  /** The staff/admin user id the reply is attributed to (assignedToId). */
  staffId: string;
}): Promise<{ error?: string; ok?: boolean; conversationUserId?: string | null }> {
  const parsed = z
    .object({ id: z.string().min(1), body: z.string().trim().min(1).max(5000) })
    .safeParse({ id: args.conversationId, body: args.body });
  if (!parsed.success) return { error: "Message must be between 1 and 5000 characters." };

  const convo = await db.chatConversation.findUnique({ where: { id: parsed.data.id } });
  if (!convo) return { error: "Conversation not found." };

  await db.$transaction([
    db.chatMessage.create({
      data: { conversationId: parsed.data.id, sender: "agent", body: parsed.data.body },
    }),
    db.chatConversation.update({
      where: { id: parsed.data.id },
      data: {
        status: "OPEN",
        unreadForUser: true,
        unreadForAgent: false,
        assignedToId: args.staffId,
        lastMessageAt: new Date(),
      },
    }),
  ]);

  // If the visitor is a signed-in customer, drop them a notification.
  if (convo.userId) {
    await db.notification
      .create({
        data: {
          userId: convo.userId,
          title: "New reply in your live chat",
          href: "/dashboard",
        },
      })
      .catch(() => {});
  }

  return { ok: true, conversationUserId: convo.userId };
}

/**
 * Shared ticket-CREATION core, extracted from lib/actions-support.ts's
 * `createTicket` for the same reason writeTicketReply/writeChatReply above
 * were: a second caller (the Discord `/support` command,
 * app/api/webhooks/discord/route.ts) needs the exact same DB-write +
 * admin-notification behavior without the form action's FormData parsing or
 * its terminal `redirect()` (which only makes sense for a page navigation,
 * not an interaction response).
 *
 * Deliberately does NOT call mirrorNewTicketToDiscord itself — that would
 * import lib/discord-bridge.ts, which already imports FROM this file
 * (writeTicketReply/writeChatReply), creating a cycle. Every caller mirrors
 * the ticket itself right after calling this, exactly as `createTicket`
 * already did before this extraction.
 *
 * NO AUTHORIZATION CHECK HERE — same discipline as writeTicketReply above.
 * Every caller must resolve/validate `userId` itself first:
 *   - `createTicket` (lib/actions-support.ts) calls `requireUser()` first.
 *   - The Discord `/support` command resolves it via `User.discordUserId`
 *     (a real, signed Discord interaction) before calling in.
 */
export async function createTicketCore(args: {
  userId: string;
  subject: string;
  body: string;
  priority?: "LOW" | "NORMAL" | "HIGH" | "URGENT";
}): Promise<{ ticketId: string; subject: string }> {
  const ticket = await db.ticket.create({
    data: {
      subject: args.subject,
      priority: args.priority ?? "NORMAL",
      userId: args.userId,
      messages: { create: { body: args.body, authorId: args.userId, isStaff: false } },
    },
  });
  const admins = await db.user.findMany({ where: { role: "ADMIN" } });
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `New ticket: ${args.subject}`,
      href: `/admin/support/${ticket.id}`,
    })),
  });
  return { ticketId: ticket.id, subject: args.subject };
}

import "server-only";
import { db } from "./db";
import { sendMail, emails } from "./mailer";

/**
 * Customer-facing "ticket reply" email send governance — coalescing +
 * circuit breaker.
 *
 * WHY THIS EXISTS (2026-08-31 incident). Two customers each received a burst
 * of 12-20 separate "New reply" emails inside a few hours. Root-caused
 * against EmailLog + TicketMessage: every single one was a genuinely
 * distinct, staff-authored reply (unique body, unique timestamp, no
 * retry-loop, no duplicate rows — image attachments behaved no differently
 * than any other reply, ruling out the suspected upload-callback theory).
 * This was a human support agent working a fast-moving live conversation,
 * not a bug that resent the same message — but Gmail's per-recipient abuse
 * heuristic (421-4.7.28 "unusual rate of unsolicited mail") doesn't care that
 * the content differed, only that mail.nxeon.cloud hit one mailbox that many
 * times that fast, and it started throttling that recipient — a real
 * deliverability risk to every OTHER transactional email (password resets,
 * receipts) this domain sends. There was no dedup/rate limit anywhere in
 * this path, so nothing stopped a legitimately chatty conversation — or any
 * FUTURE bug shaped like this one — from tripping it again.
 *
 * TWO SEPARATE SAFEGUARDS, BOTH IN THIS FILE:
 *
 * 1. COALESCE WINDOW (`TICKET_REPLY_COALESCE_MS`) — staff replies to the same
 *    ticket that land within this window of an already-sent email do not
 *    each get their own email. `maybeSendTicketReplyEmail` (called inline,
 *    right after a staff TicketMessage is written) sends immediately when
 *    the ticket has been quiet — the common case, zero added latency. When
 *    it's NOT quiet (we're inside another send's window), it does nothing
 *    and leaves the burst for `worker/ticket-reply-digest.ts`'s periodic
 *    sweep to flush as ONE email once the burst goes quiet — bounded delay,
 *    nothing silently dropped. Real support replies are normally minutes to
 *    hours apart, so this never delays a normal conversation; it only
 *    collapses genuine rapid-fire bursts (human or bug).
 *
 * 2. DAILY CAP (`TICKET_REPLY_DAILY_CAP`) — a hard circuit breaker,
 *    independent of the coalescing above. If a single customer would cross
 *    this many ticket_reply emails in a rolling 24h window, further sends
 *    stop automatically and staff get an admin Notification instead of the
 *    customer getting another email — a backstop against ANY future bug
 *    shaped like this one, not just today's specific cause. Deliberately NOT
 *    a flat "once per day" limit — a real multi-touch ticket (status update,
 *    then "fixed" a few hours later) must not get throttled into a bad
 *    support experience; the cap only bites at genuinely abnormal volume.
 *
 * Neither safeguard touches the TicketMessage write, the in-app bell
 * notification, or the Discord mirror — those still fire on every reply.
 * Only the outbound customer email is governed here.
 */

/** Staff replies to the same ticket inside this window of an already-sent
 *  email collapse into a single follow-up email instead of one each. */
export const TICKET_REPLY_COALESCE_MS = 2 * 60_000;

/** Circuit breaker: max ticket_reply emails one customer may receive in a
 *  rolling 24h window before further ones are suppressed and flagged. */
export const TICKET_REPLY_DAILY_CAP = 5;

const DAILY_WINDOW_MS = 24 * 3600_000;

/** The subject tag `emails.ticketReply` stamps on every send — used to scope
 *  EmailLog lookups to THIS ticket without a schema change. */
export function ticketReplyEmailTag(ticketId: string): string {
  return `[#${ticketId}]`;
}

/** How many ticket_reply emails has this customer been sent in the last 24h? */
export async function ticketReplyDailyCount(customerUserId: string, now: Date = new Date()): Promise<number> {
  return db.emailLog.count({
    where: {
      userId: customerUserId,
      template: "ticket_reply",
      status: "SENT",
      createdAt: { gte: new Date(now.getTime() - DAILY_WINDOW_MS) },
    },
  });
}

/** Most recent SENT ticket_reply email for this exact ticket, if any. */
async function lastSentTicketReplyEmail(ticketId: string, customerUserId: string): Promise<{ createdAt: Date } | null> {
  return db.emailLog.findFirst({
    where: {
      userId: customerUserId,
      template: "ticket_reply",
      status: "SENT",
      subject: { startsWith: ticketReplyEmailTag(ticketId) },
    },
    orderBy: { createdAt: "desc" },
    select: { createdAt: true },
  });
}

/**
 * Flag the daily cap having been reached for staff attention. Deduped to at
 * most one admin Notification per ticket per hour so a still-active
 * conversation past the cap doesn't spam the admin bell on every further
 * reply attempt.
 */
export async function flagTicketReplyDailyCapReached(ticketId: string, ticketSubject: string): Promise<void> {
  const dedupeSince = new Date(Date.now() - 60 * 60_000);
  const href = `/admin/support/${ticketId}`;
  const already = await db.notification.findFirst({
    where: { href, title: { startsWith: "⚠️ Ticket reply emails paused" }, createdAt: { gte: dedupeSince } },
  });
  if (already) return;
  console.warn(
    `[support] ticket-reply daily email cap (${TICKET_REPLY_DAILY_CAP}/24h) reached for ticket ${ticketId} — further customer emails suppressed until it rolls off`,
  );
  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length === 0) return;
  await db.notification.createMany({
    data: admins.map((a) => ({
      userId: a.id,
      title: `⚠️ Ticket reply emails paused (daily cap reached): ${ticketSubject}`,
      href,
    })),
  });
}

/** Actually render + send the customer-facing "ticket reply" email. No
 *  governance here — callers (the fast path below, and the digest sweep)
 *  are responsible for deciding it's OK to send. */
export async function sendTicketReplyEmailNow(
  ticketId: string,
  customerUserId: string,
  customerEmail: string,
  ticketSubject: string,
  replyPreview: string,
): Promise<void> {
  const tpl = emails.ticketReply({ ticketId, subject: ticketSubject, replyPreview });
  await sendMail({
    to: customerEmail,
    subject: tpl.subject,
    html: tpl.html,
    template: tpl.template,
    userId: customerUserId,
    kind: "support_reply",
  });
}

/**
 * Called synchronously right after a staff TicketMessage is written
 * (`lib/reply-core.ts`'s `writeTicketReply`). Fast path for the normal case;
 * defers to `worker/ticket-reply-digest.ts`'s sweep when we're mid-burst.
 * Never throws — a mail failure or governance skip must never fail the reply
 * itself; callers still wrap this in their own try/catch as defense in depth.
 */
export async function maybeSendTicketReplyEmail(args: {
  ticketId: string;
  ticketUserId: string;
  ticketSubject: string;
  replyBody: string;
}): Promise<void> {
  const sentToday = await ticketReplyDailyCount(args.ticketUserId);
  if (sentToday >= TICKET_REPLY_DAILY_CAP) {
    await flagTicketReplyDailyCapReached(args.ticketId, args.ticketSubject);
    return;
  }

  const lastSent = await lastSentTicketReplyEmail(args.ticketId, args.ticketUserId);
  if (lastSent && Date.now() - lastSent.createdAt.getTime() < TICKET_REPLY_COALESCE_MS) {
    // Inside another send's coalesce window — leave this burst for the
    // digest sweep to flush as one email once it goes quiet.
    console.info("[support] staff-reply email deferred to digest sweep (coalesce window)", args.ticketId);
    return;
  }

  const customer = await db.user.findUnique({ where: { id: args.ticketUserId }, select: { email: true } });
  if (!customer?.email) return;
  await sendTicketReplyEmailNow(args.ticketId, args.ticketUserId, customer.email, args.ticketSubject, args.replyBody);
}
// Ticket-reply email digest sweep (worker task).
//
// Registered on the worker loop (worker/index.ts). Flushes the "one email per
// burst" side of `lib/ticket-reply-email.ts`'s coalescing safeguard — see that
// file's top-of-file comment for the full incident writeup and design.
//
// `maybeSendTicketReplyEmail` (called inline from `lib/reply-core.ts` right
// after a staff reply is written) sends immediately when a ticket has been
// quiet for a while (the common case). When a new staff reply lands inside
// another send's `TICKET_REPLY_COALESCE_MS` window, it deliberately does
// NOTHING — no email goes out for that reply. This sweep is what guarantees
// that burst still gets exactly ONE follow-up email once it goes quiet,
// instead of the customer's latest update just silently never being mailed.
//
// FINDING CANDIDATES WITHOUT A SCHEMA CHANGE: there is no "pending digest"
// column anywhere. Instead this derives pending state from data that already
// exists — any ticket with a staff-authored TicketMessage newer than that
// ticket's most recent SENT `ticket_reply` EmailLog row is "behind" and needs
// a catch-up email once the newest such message has been quiet long enough.
// Scoped to staff messages from the last 30 minutes: `TICKET_REPLY_COALESCE_MS`
// is only 2 minutes, so anything that could still be "pending and not yet
// quiet long enough" is always well inside that lookback; this just bounds
// the scan to recent activity instead of walking every ticket that ever
// existed. (If ticket volume grows enough for this per-tick scan to matter,
// the natural next step is a real `pendingReplyEmailSince` column — not done
// here since the current volume makes it unnecessary and this ships faster
// without a migration during an active incident.)
//
// Polled every ~20s (see worker/index.ts) — short enough that the 2-minute
// coalesce window doesn't turn into a much longer real-world delay.

import { db } from "../lib/db";
import {
  TICKET_REPLY_COALESCE_MS,
  TICKET_REPLY_DAILY_CAP,
  ticketReplyEmailTag,
  ticketReplyDailyCount,
  flagTicketReplyDailyCapReached,
  sendTicketReplyEmailNow,
} from "../lib/ticket-reply-email";

/** How far back to look for candidate tickets. Generous relative to the
 *  2-minute coalesce window so a sweep hiccup can't miss a pending burst. */
const CANDIDATE_LOOKBACK_MS = 30 * 60_000;

/** Bounded per-sweep-tick send budget — mirrors the pattern in
 *  lib/critical-email-retry.ts: a backlog can't hammer the mail relay. */
const MAX_SENDS_PER_SWEEP = 20;

/** Gentle pacing between sends within one sweep tick. */
const SEND_GAP_MS = 500;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function ticketReplyDigestSweep(): Promise<void> {
  const since = new Date(Date.now() - CANDIDATE_LOOKBACK_MS);

  // Distinct tickets that had a staff reply recently — candidates for "is
  // this ticket behind on its customer-facing email?".
  const recentStaffMessages = await db.ticketMessage.findMany({
    where: { isStaff: true, createdAt: { gte: since } },
    distinct: ["ticketId"],
    select: { ticketId: true },
  });
  if (recentStaffMessages.length === 0) return;

  let sent = 0;
  for (const { ticketId } of recentStaffMessages) {
    if (sent >= MAX_SENDS_PER_SWEEP) break;

    const latestStaffMessage = await db.ticketMessage.findFirst({
      where: { ticketId, isStaff: true },
      orderBy: { createdAt: "desc" },
      select: { createdAt: true, body: true },
    });
    if (!latestStaffMessage) continue;

    // Still inside the coalesce window since this ticket's newest staff
    // reply — not quiet yet, leave it for a later tick (or the inline fast
    // path may still catch it if this is actually the very first reply).
    if (Date.now() - latestStaffMessage.createdAt.getTime() < TICKET_REPLY_COALESCE_MS) continue;

/**
 * Notification preferences: the stored shape, the pure helpers — and the POLICY
 * that decides which messages those preferences are allowed to suppress.
 *
 * Plain module (safe to import from server components; client components must
 * import TYPES ONLY — the `mayDeliverTo` helper below reaches for `./db`). The
 * `"use server"` action file may only export async functions, so all of this
 * lives here.
 *
 * WHY THIS FILE GREW A POLICY (2026-07-26)
 * ---------------------------------------------------------------------------
 * `User.notificationPrefs` was written by the settings form and read by NOTHING
 * (QA-PRELAUNCH P1-32). A customer who unticked "Account email" still received
 * every receipt; the "Security alerts" toggle governed a channel that was never
 * built. That is the same defect this codebase keeps shipping: a control that
 * reports success and is read by nothing — the auto-suspend kill switch an
 * operator turned off before watching customer VMs get suspended anyway
 * (P1-5), and the domain-markup panel that displayed 0% while charging 25%
 * (P1-9).
 *
 * The dangerous half of fixing it is OVER-fixing it. If a preference could
 * suppress a declined payment, an imminent suspension, a security/2FA change or
 * a data-loss warning, then an unticked checkbox would silently swallow the one
 * message the customer had to see — and they would lose a server, or an
 * account, with no warning at all. That is strictly worse than the original bug.
 *
 * So suppressibility is decided by a message's TIER, declared once in the
 * catalogue below, and never by the call site. A send site cannot make itself
 * suppressible by passing the wrong flag, and an unrecognised kind resolves to
 * CRITICAL — if we guess wrong, we guess towards "delivered".
 */

export type NotificationPrefs = {
  /**
   * Non-urgent transactional EMAIL: payment receipts, activity notices.
   * Never covers the dunning sequence, suspensions or security changes.
   */
  email: boolean;
  /**
   * Product news / marketing. Unticking this also removes the address from the
   * campaign list (see `updateNotificationPrefs`) — the stored flag alone would
   * suppress nothing, because campaigns are addressed by email, not by user.
   */
  product: boolean;
  /**
   * Legacy key, pinned `true`.
   *
   * It used to render as a "Security alerts" toggle, which was dishonest twice
   * over: the channel it claimed to govern was never built (sign-in / token /
   * 2FA paths write audit rows only), and security, password and 2FA messages
   * must not be suppressible in the first place. Kept in the shape so
   * previously-stored values and the GDPR export keep round-tripping, and typed
   * as the literal `true` so no code path can ever write it back as
   * consent-withdrawn.
   */
  security: true;
};

export const DEFAULT_PREFS: NotificationPrefs = { email: true, product: true, security: true };

/**
 * Normalise whatever is stored in the Json column into a typed prefs object.
 * A missing or malformed key falls back to the default (opted IN) — the column
 * is nullable and predates this policy, so "absent" must never read as "the
 * customer opted out of everything".
 */
export function normalizePrefs(raw: unknown): NotificationPrefs {
  const p = (raw ?? {}) as Record<string, unknown>;
  return {
    email: typeof p.email === "boolean" ? p.email : DEFAULT_PREFS.email,
    product: typeof p.product === "boolean" ? p.product : DEFAULT_PREFS.product,
    security: true,
  };
}

/* -------------------------------------------------------------------------- */
/*                          Delivery policy                                   */
/* -------------------------------------------------------------------------- */

/** How a message reaches the customer. */
export type NotifyChannel = "email" | "inapp";

/**
 * Suppressibility tier.
 *
 * CRITICAL — "you need to know this". Delivered on every channel, always,
 *            whatever the preferences say. Money that failed to move, a service
 *            about to be suspended or deleted, a change to how the account is
 *            secured, or anything that can cost the customer data.
 * ACCOUNT  — informational transactional. Email is suppressible via
 *            `prefs.email`; the in-app bell is kept (see `isSuppressible`).
 * PRODUCT  — marketing. Suppressible on every channel via `prefs.product`.
 */
export type NotifyTier = "CRITICAL" | "ACCOUNT" | "PRODUCT";

/**
 * Every message kind the platform can send, and the ONE thing that decides
 * whether a preference may hold it back. Grouped by tier so the split is
 * reviewable at a glance — adding a kind is a deliberate act, and putting
 * something in ACCOUNT is a statement that a customer missing it entirely costs
 * them nothing they cannot recover.
 */
export const NOTIFY_KINDS = {
  // ---- CRITICAL: never suppressible, on any channel, by any preference. -----
  /** Password-reset link. The only way back into a locked-out account. */
  password_reset: "CRITICAL",
  /**
   * Email-verification link. CRITICAL for the same reason as the reset link, not
   * because it is urgent: an unverified account cannot buy or provision
   * (lib/email-verification.ts), so this message is the ONLY way past that gate.
   * Letting a preference suppress it would leave the customer refused at
   * checkout with no way to fix it — a locked door whose key we withheld.
   */
  email_verify: "CRITICAL",
  /** Password changed, 2FA enabled/disabled, backup codes reissued, API token created/revoked. */
  security_change: "CRITICAL",
  /** Card declined, dunning retry declined, final notice. Money did not move. */
  payment_failed: "CRITICAL",
  /** 3-D Secure / `requires_action` — the payment stalls until the customer acts. */
  payment_action_required: "CRITICAL",
  /** Saved card expires soon: the next renewal will fail if it is not replaced. */
  card_expiring: "CRITICAL",
  /** Term is about to lapse. Suppressing this is how a paid-up customer loses a VM. */
  expiry_warning: "CRITICAL",
  /** Service suspended, or about to be. */
  suspension: "CRITICAL",
  /** Service terminated, or about to be — data destruction is imminent/done. */
  termination: "CRITICAL",
  /** Abuse / acceptable-use action against the account. */
  abuse: "CRITICAL",
  /** Anything that lost, or may lose, customer data (failed backup, restore, volume). */
  data_loss: "CRITICAL",
  /** Paid but not provisioned — the customer's money is in limbo. */
  fulfilment_failed: "CRITICAL",
  /**
   * Server provisioned and reachable — the deployment confirmation carrying the
   * customer's SSH connection details. The positive resolution of the same
   * money-path as `fulfilment_failed`, and CRITICAL for the same reason: it must
   * ALWAYS send. A stranded customer whose status was silently wrong (see the
   * reconcile recovery) may never have received it, so suppressing it by a
   * preference would leave someone who paid for a server unable to find the door.
   */
  provision_ready: "CRITICAL",
  /** Refund or write-off issued against the account. */
  refund: "CRITICAL",

  // ---- ACCOUNT: informational transactional. Email opt-out honoured. -------
  welcome: "ACCOUNT",
  /** Receipt for a payment that SUCCEEDED. (A failure is `payment_failed`.) */
  receipt: "ACCOUNT",
  invoice: "ACCOUNT",
  /** Deploy / reinstall / migration finished successfully. */
  provision_done: "ACCOUNT",
  /** Backup taken, app installed, certificate issued, volume attached, … */
  job_done: "ACCOUNT",
  /** Domain registered / renewed / transferred. */
  domain_activity: "ACCOUNT",
  support_reply: "ACCOUNT",
  referral_bonus: "ACCOUNT",

  // ---- PRODUCT: marketing. Suppressible everywhere. ------------------------
  product_news: "PRODUCT",
} as const satisfies Record<string, NotifyTier>;

export type NotifyKind = keyof typeof NOTIFY_KINDS;

/**
 * Tier of a message kind. An unregistered kind resolves to CRITICAL on purpose:
 * the failure mode of a mis-typed or forgotten kind must be "delivered anyway",
 * never "silently dropped".
 */
export function notifyTier(kind: NotifyKind): NotifyTier {
  return (NOTIFY_KINDS as Record<string, NotifyTier>)[kind] ?? "CRITICAL";
}

/**
 * Does this (kind, channel) pair depend on the customer's preferences at all?
 *
 * `false` means the answer is unconditionally "deliver", so callers can skip the
 * preference lookup entirely — the gate costs nothing on the critical paths.
 */
export function isSuppressible(kind: NotifyKind, channel: NotifyChannel): boolean {
  const tier = notifyTier(kind);
  if (tier === "CRITICAL") return false;
  if (tier === "ACCOUNT") {
    // Email only. The in-app bell is the durable record inside the portal, and
    // the toggle the customer ticked says "email" — hiding an activity notice
    // from the portal would recreate the very failure this policy exists to
    // cure (information that quietly went missing), while suppressing the mail
    // is exactly what was asked for.
    return channel === "email";
  }
  return true; // PRODUCT — marketing has no business on a channel they declined.
}

/** Decide delivery from already-loaded preferences. */
export function mayDeliver(
  prefs: NotificationPrefs,
  kind: NotifyKind,
  channel: NotifyChannel,
): boolean {
  if (!isSuppressible(kind, channel)) return true;
  return notifyTier(kind) === "PRODUCT" ? prefs.product : prefs.email;
}

/**
 * Decide delivery for a user id, loading their preferences only when the answer
 * actually depends on them.
 *
 * Fails OPEN. A missing user row or a database hiccup returns `true`: a message
 * must never be dropped because a preference lookup failed — that would be a
 * silent swallow with no preference behind it at all.
 *
 * `./db` is imported lazily so this module stays statically safe to import from
 * anywhere (the settings page imports `normalizePrefs`, the client component
 * imports the type only).
 */
export async function mayDeliverTo(
  userId: string,
  kind: NotifyKind,
  channel: NotifyChannel,
): Promise<boolean> {
  if (!isSuppressible(kind, channel)) return true;
  try {
    const { db } = await import("./db");
    const row = await db.user.findUnique({
      where: { id: userId },
      select: { notificationPrefs: true },
    });
    if (!row) return true;
    return mayDeliver(normalizePrefs(row.notificationPrefs), kind, channel);
  } catch {
    return true;
  }
}
"use server";

import { revalidatePath } from "next/cache";
import { db } from "./db";
import { requireUser } from "./auth";
import type { NotificationPrefs } from "./prefs";

/**
 * Save notification preferences from the settings form.
 *
 * Ownership: `requireUser()` and the write is keyed on that user's own id — this
 * action takes no user id from the client, so it can only ever edit the caller.
 */
export async function updateNotificationPrefs(
  prev: unknown,
  formData: FormData,
): Promise<{ ok?: boolean; error?: string; note?: string }> {
  const user = await requireUser();
  const prefs: NotificationPrefs = {
    email: formData.get("email") === "on",
    product: formData.get("product") === "on",
    // Pinned true — see `NotificationPrefs.security`. Security, password and 2FA
    // messages are CRITICAL and must never be suppressible, so there is no
    // toggle for them and nothing may store a withdrawal of consent for them.
    security: true,
  };
  await db.user.update({ where: { id: user.id }, data: { notificationPrefs: prefs } });

  // Make "Product updates" real TODAY, not once someone else wires it.
  //
  // Campaigns are addressed from `NewsletterSubscriber` BY EMAIL ADDRESS
  // (lib/actions-newsletter-campaign.ts) — a table with no relation to `User` —
  // so storing `product: false` on the user suppresses precisely nothing. That
  // was the P1-32 failure at its worst: the customer withdraws marketing consent,
  // sees "Saved ✓", and the next campaign still lands in their inbox. For a
  // UK/EU customer that is a consent obligation, not a UX nicety.
  //
  // Deliberately one-way: turning the toggle ON does NOT subscribe them. This
  // form posts every checkbox on every save and `product` defaults to ticked, so
  // auto-subscribing would add customers to a marketing list as a side effect of
  // saving an unrelated preference. A toggle may withdraw consent; it must never
  // manufacture it.
  let note: string | undefined;
  if (!prefs.product) {
    const removed = await db.newsletterSubscriber.deleteMany({
      where: { email: user.email.toLowerCase() },
    });
    if (removed.count > 0) note = "Removed from the product-news list.";
  }

