"use server";

import { createHash, randomBytes } from "crypto";
import { revalidatePath } from "next/cache";
import { requireUser, assertNotImpersonating } from "@/lib/auth";
import { db } from "@/lib/db";

/* Settings actions for the account area.
 *
 * `"use server"` makes EVERY export here network-callable, so each one calls
 * `requireUser()` itself and scopes every write to that user's own id. There is
 * no shared "already checked" state between them — a caller reaching one export
 * directly must be authorised by that export.
 *
 * Nothing here touches money, notification delivery, or anything that could
 * suppress a message: notification preferences live in `User.notificationPrefs`
 * behind lib/prefs.ts, which owns the policy about what may be suppressed.
 */

export type Res = { ok?: boolean; error?: string; value?: string };

const THEMES = new Set(["dark", "light", "system"]);
const DATE_FORMATS = new Set(["DMY", "MDY", "ISO"]);
const PER_PAGE = new Set([10, 25, 50, 100]);

/** Display preferences. Display only — none of this decides what is charged. */
export async function saveDisplayPrefs(_p: Res | undefined, form: FormData): Promise<Res> {
  const user = await requireUser();
  const theme = String(form.get("theme") ?? "dark");
  const dateFormat = String(form.get("dateFormat") ?? "DMY");
  const itemsPerPage = Number(form.get("itemsPerPage") ?? 25);
  const defaultPage = String(form.get("defaultPage") ?? "/dashboard");

  /* Validated against a closed set rather than stored as typed. A free string
     here would come back out into a `className` or a route. */
  if (!THEMES.has(theme)) return { error: "Unknown theme." };
  if (!DATE_FORMATS.has(dateFormat)) return { error: "Unknown date format." };
  if (!PER_PAGE.has(itemsPerPage)) return { error: "Unsupported page size." };
  if (!defaultPage.startsWith("/dashboard")) return { error: "That page is not a dashboard page." };

  await db.userPreference.upsert({
    where: { userId: user.id },
    create: { userId: user.id, theme, dateFormat, itemsPerPage, defaultPage },
    update: { theme, dateFormat, itemsPerPage, defaultPage },
  });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

/** Issue an API key. The plaintext is returned ONCE and never stored. */
export async function createApiKey(_p: Res | undefined, form: FormData): Promise<Res> {
  const user = await requireUser();
  await assertNotImpersonating();
  const name = String(form.get("name") ?? "").trim().slice(0, 60);
  const scope = String(form.get("scope") ?? "full");
  if (name.length < 2) return { error: "Give the key a name you will recognise later." };
  if (!["full", "servers:read", "metrics:read"].includes(scope)) return { error: "Unknown scope." };

  const live = await db.apiKey.count({ where: { userId: user.id, revokedAt: null } });
  if (live >= 20) return { error: "You already have 20 active keys. Revoke one first." };

  /* 32 bytes of CSPRNG. The database gets only the SHA-256 and a display
     prefix, so a dump of this table is not a set of working credentials. */
  const secret = randomBytes(32).toString("base64url");
  const key = `nxk_live_${secret}`;
  await db.apiKey.create({
    data: {
      userId: user.id, name, scope,
      keyHash: createHash("sha256").update(key).digest("hex"),
      prefix: key.slice(0, 13),
    },
  });
  revalidatePath("/dashboard/settings");
  /* The one and only time this value exists outside the caller's hands. */
  return { ok: true, value: key };
}

export async function revokeApiKey(id: string): Promise<Res> {
  const user = await requireUser();
  await assertNotImpersonating();
  /* Scoped to the caller's own id in the WHERE, not checked afterwards — a
     mismatched id updates nothing rather than revoking someone else's key. */
  const r = await db.apiKey.updateMany({
    where: { id, userId: user.id, revokedAt: null },
    data: { revokedAt: new Date() },
  });
  if (r.count === 0) return { error: "That key is already revoked, or is not yours." };
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

export async function revokeSession(id: string): Promise<Res> {
  const user = await requireUser();
  await assertNotImpersonating();
  const r = await db.userSession.updateMany({
    where: { id, userId: user.id, revokedAt: null },
    data: { revokedAt: new Date() },
  });
  if (r.count === 0) return { error: "That session has already ended." };
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

/** End every OTHER session. The current one is left alone deliberately —
 *  signing yourself out of the page you are standing on is not what the
 *  control means. */
export async function revokeOtherSessions(currentTokenHash: string): Promise<Res> {
  const user = await requireUser();
  await assertNotImpersonating();
  const r = await db.userSession.updateMany({
    where: { userId: user.id, revokedAt: null, NOT: { tokenHash: currentTokenHash } },
    data: { revokedAt: new Date() },
  });
  revalidatePath("/dashboard/settings");
  return { ok: true, value: String(r.count) };
}

import { createHash } from "node:crypto";
import type { User } from "@prisma/client";

/**
 * Prisma on demand. `hashToken`, `extractBearer` and `tokenHasScope` are pure,
 * and `tokenHasScope` is an authorization decision — the kind of thing that has
 * to be exercised directly by a test rather than reasoned about. A top-level
 * `import { db }` made that impossible without pointing Prisma at the production
 * DATABASE_URL in /opt/nxeon/.env just to evaluate a string comparison.
 */
async function prisma() {
  return (await import("./db")).db;
}

/**
 * Bearer-token authentication for the public REST API (`/api/v1/*`).
 *
 * Tokens are formatted `nxe_<prefix>_<random>` and only their sha256 hash is
 * stored (never the plaintext). Given an incoming request, resolve the bearer
 * token to its owning user, honouring `revoked` and `expiresAt`, and stamp
 * `lastUsedAt`.
 */

export const TOKEN_PREFIX = "nxe";

/** Extract the raw bearer token from an `Authorization: Bearer …` header. */
export function extractBearer(req: Request): string | null {
  const header = req.headers.get("authorization") ?? req.headers.get("Authorization");
  if (!header) return null;
  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
  return match ? match[1].trim() : null;
}

/** sha256 hex hash of a token — the value stored in `ApiToken.tokenHash`. */
export function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

export type ApiAuthResult =
  | { ok: true; user: User; tokenId: string; scopes: string[] }
  | { ok: false; status: number; error: string };

/**
 * Authenticate an API request by its bearer token.
 * Returns the resolved user + token scopes, or a structured error with an
 * appropriate HTTP status for the route to return.
 */
export async function authenticateApiToken(req: Request): Promise<ApiAuthResult> {
  const raw = extractBearer(req);
  if (!raw) return { ok: false, status: 401, error: "Missing bearer token" };
  if (!raw.startsWith(`${TOKEN_PREFIX}_`)) {
    return { ok: false, status: 401, error: "Invalid token format" };
  }

  const db = await prisma();
  const tokenHash = hashToken(raw);
  const token = await db.apiToken.findUnique({
    where: { tokenHash },
    include: { user: true },
  });

  if (!token) return { ok: false, status: 401, error: "Invalid token" };
  if (token.revoked) return { ok: false, status: 401, error: "Token has been revoked" };
  if (token.expiresAt && token.expiresAt < new Date()) {
    return { ok: false, status: 401, error: "Token has expired" };
  }
  if (!token.user || token.user.suspended) {
    return { ok: false, status: 403, error: "Account unavailable" };
  }

  // Best-effort lastUsedAt stamp — never block the request on this write.
  db.apiToken
    .update({ where: { id: token.id }, data: { lastUsedAt: new Date() } })
    .catch(() => {});

  return { ok: true, user: token.user, tokenId: token.id, scopes: token.scopes };
}

/**
 * Whether an authenticated token carries a given scope.
 *
 * A scope is `resource:action` (`servers:read`). A token satisfies a request if
 * it carries:
 *   - the exact requested scope, or
 *   - the global wildcard `*`, or
 *   - the resource wildcard `servers:*`, or
 *   - the generic `read` scope, which satisfies any `*:read` request.
 *
 * ── EMPTY SCOPES ARE READ-ONLY, NOT FULL ACCESS ──────────────────────────────
 *
 * A token with no scopes recorded predates scoping. It used to return true for
 * ANY request — `if (scopes.length === 0) return true` — which is not
 * "backward compatible", it is "unscoped means unlimited". It survived review
 * only because the public API happens to be read-only today: `GET /api/v1/servers`
 * is the single token-authenticated route in the codebase. The first mutating
 * endpoint to land would have silently granted every legacy token the right to
 * call it, and nobody adding that endpoint would have had any reason to look here.
 *
 * A customer who created a token before scopes existed consented to reading their
 * account, because reading is all the API could do. They did not consent to a
 * future `servers:delete`. So an empty scope list now means exactly that: reads,
 * and nothing else. Fail closed, and let the failure be a 403 on a new endpoint
 * rather than a deletion nobody authorised.
 */
export function tokenHasScope(auth: ApiAuthResult, scope: string): boolean {
  if (!auth.ok) return false;
  if (!scope || typeof scope !== "string") return false;
  const scopes = auth.scopes ?? [];
  const [resource, action] = scope.split(":");

  if (scopes.length === 0) {
    // Legacy, pre-scoping token: reads only. `servers:read` yes, anything that
    // changes state no.
    return action === "read";
  }
  if (scopes.includes("*") || scopes.includes(scope)) return true;
  if (resource && scopes.includes(`${resource}:*`)) return true;
  if (action === "read" && scopes.includes("read")) return true;
  return false;
}

/**
 * Authenticate AND authorize in one call — the form every `/api/v1` route should
 * use.
 *
 * `tokenHasScope` on its own is advisory: nothing makes a route call it, and a
 * route that forgets is authenticated-but-unauthorized, which looks completely
 * normal in review. That is the second half of the same footgun, and it cannot be
 * fixed by being careful. It is fixed by there being a single entry point that
 * cannot answer "who is this" without also being told "to do what", plus the
 * tripwire in test/api-http-surface.test.ts asserting that no route under
 * app/api/v1 authenticates a token without checking a scope.
 *
 * Returns the same discriminated union as `authenticateApiToken`, so a route
 * handles one error shape:
 *
 *     const auth = await authorizeApiRequest(req, "servers:read");
 *     if (!auth.ok) return NextResponse.json({ error: auth.error }, { status: auth.status });
 */
export async function authorizeApiRequest(
  req: Request,
  scope: string,
): Promise<ApiAuthResult> {
  const auth = await authenticateApiToken(req);
  if (!auth.ok) return auth;
  if (!tokenHasScope(auth, scope)) {
    return { ok: false, status: 403, error: `Token is missing the required scope: ${scope}` };
  }
  return auth;
}
