import { SignJWT, jwtVerify, type JWTPayload } from "jose";
import { cookies } from "next/headers";
import { cache } from "react";
import { db } from "./db";
import { getSettingInt } from "./settings";
import type { User } from "@prisma/client";

const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";

export async function createSession(userId: string) {
  // Session lifetime is admin-configurable (`session_length_days`, default 30).
  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
  const days = Math.max(1, await getSettingInt("session_length_days", 30));
  // Embed the account's current sessionVersion so a bump (password change/reset)
  // invalidates every previously-issued token. Missing => treated as 0.
  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
  // `typ` distinguishes this from the impersonation token below. Both are signed
  // with the SAME secret, so without it the two are interchangeable strings —
  // see the note on `assertSessionToken`.
  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0, typ: "session" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime(`${days}d`)
    .sign(secret);
  const jar = await cookies();
  // Secure in production regardless of COOKIE_SECURE, matching the impersonation
  // cookie — a deploy that forgets COOKIE_SECURE=1 must not ship a non-Secure
  // session cookie. Local http dev stays non-secure (NODE_ENV !== "production").
  const secure = process.env.NODE_ENV === "production";
  jar.set(COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure,
    maxAge: 60 * 60 * 24 * days,
    path: "/",
  });
  // Non-sensitive, JS-readable flag so the (static) marketing header can show
  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
  // no identity — just presence. Always cleared alongside the session cookie.
  jar.set("nxeon_authed", "1", {
    httpOnly: false,
    sameSite: "lax",
    secure,
    maxAge: 60 * 60 * 24 * days,
    path: "/",
  });
}

export async function destroySession() {
  const jar = await cookies();
  jar.delete(COOKIE);
  jar.delete("nxeon_authed");
}

/**
 * Is this payload allowed to act as a SESSION, as opposed to an impersonation
 * grant?
 *
 * Both cookies are HS256 over the same `AUTH_SECRET`, so as far as `jwtVerify`

const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;

/** The real signed-in account, ignoring any impersonation. */
export const realUser = cache(async (): Promise<User | null> => {
  const jar = await cookies();
  const token = jar.get(COOKIE)?.value;
  if (!token) return null;
  try {
    const { payload } = await jwtVerify(token, secret);
    if (!payload.sub) return null;
    // An impersonation grant is not a session (see assertSessionToken).
    if (!assertSessionToken(payload)) return null;
    const user = await db.user.findUnique({ where: { id: payload.sub } });
    if (!user || user.suspended) return null;
    // Session revocation: a token is only valid while its embedded version matches
    // the account's current sessionVersion. Older tokens without `sv` count as 0,
    // so accounts that never bumped stay logged in (backward-compatible).
    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
    return user;
  } catch {
    return null;
  }
});

"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { headers } from "next/headers";
import bcrypt from "bcryptjs";
import { z } from "zod";
import { db } from "./db";
import {
  requireUser,
  requireAdmin,
  setImpersonation,
  clearImpersonation,
  createSession,
} from "./auth";
import { checkRateLimit, clientIp } from "./rate-limit";
import { mayDeliverTo } from "./prefs";
import { normalizeEmail } from "./email-normalize";
import { normalizeHeardSource } from "./heard-about";

// ---------- Profile ----------

export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
  await db.user.update({ where: { id: user.id }, data: { name } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}

export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const current = String(formData.get("current") ?? "");
  const next = String(formData.get("next") ?? "");
  if (next.length < 8) return { error: "New password must be at least 8 characters." };
  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
  // Bump sessionVersion to evict every other outstanding session, then re-issue a
  // fresh token for THIS session so the user who changed the password stays in.
  await db.user.update({
    where: { id: user.id },
    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
  });
  await createSession(user.id);
  return { ok: true };
}

/**
 * Evict every OTHER logged-in session for this account (a stolen/borrowed device,
 * a shared computer left signed in) while keeping the caller signed in. Same
 * mechanism as a password change: bump sessionVersion so every existing token
 * fails the version check, then re-issue a fresh token for THIS session.
 */
export async function signOutOtherSessions(): Promise<{ ok?: boolean; error?: string }> {
  const user = await requireUser();
  await db.user.update({
    where: { id: user.id },
    data: { sessionVersion: { increment: 1 } },
  });
  await createSession(user.id);
  return { ok: true };
}

// ---------- "How did you hear about us?" survey ----------

/**
 * Record the customer's answer to the one-time acquisition survey.
 *
 * `source` is validated against the allowed channel keys + "skipped" + the
 * "other:<free text>" shape (the free text is trimmed, control-stripped and
 * capped ~120 chars — see normalizeHeardSource). An unrecognised value is
 * silently dropped.
 *
 * "Asked once" is enforced at the write: we only set heardAboutUs when it is
 * still null, using an `updateMany` guarded by `heardAboutUs: null`. A second
 * call (or a race between two tabs) after any value — a channel OR "skipped" —
 * is a no-op and never overwrites the first answer. Always returns { ok: true }
 * so the client can close the prompt regardless.
 */
export async function setHeardAboutUs(source: string): Promise<{ ok: true }> {
  const user = await requireUser();
  const value = normalizeHeardSource(source);
  if (!value) return { ok: true };
  await db.user.updateMany({
    where: { id: user.id, heardAboutUs: null },
    data: { heardAboutUs: value },
  });
  // The dashboard LAYOUT gates the prompt on `heardAboutUs`, not any one page
  // — revalidate the whole subtree, or a client-side nav to a route Next has
  // already cached (from before this write) can render the layout without
  // ever re-checking the field, and the prompt reappears despite the DB
  // already being correct.
  revalidatePath("/dashboard", "layout");
  return { ok: true };
}

// ---------- SSH keys ----------

export async function addSshKey(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const parsed = z
    .object({
      name: z.string().min(1).max(60),
      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
    })
    .safeParse({ name: formData.get("name"), publicKey: String(formData.get("publicKey") ?? "").trim() });
  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid key." };
  await db.sshKey.create({ data: { userId: user.id, ...parsed.data } });
  revalidatePath("/dashboard/settings");
  return {};
}

export async function deleteSshKey(keyId: string) {
  const user = await requireUser();
  await db.sshKey.deleteMany({ where: { id: keyId, userId: user.id } });
  revalidatePath("/dashboard/settings");
}

// ---------- Projects ----------

export async function createProject(prev: any, formData: FormData): Promise<{ error?: string }> {
  const user = await requireUser();
  const name = String(formData.get("name") ?? "").trim();
  const color = String(formData.get("color") ?? "#6f47f5");
  if (name.length < 1 || name.length > 50) return { error: "Project name: 1–50 characters." };
  await db.project.create({ data: { userId: user.id, name, color } });
  revalidatePath("/dashboard/projects");
  return {};
}

export async function deleteProject(projectId: string) {
  const user = await requireUser();
  await db.project.deleteMany({ where: { id: projectId, userId: user.id } });
  revalidatePath("/dashboard/projects");
}

export async function assignServerProject(serverId: string, projectId: string | null) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
  if (projectId) {
    const project = await db.project.findFirst({ where: { id: projectId, userId: server.userId } });
    if (!project) throw new Error("Project not found");
  }
  await db.server.update({ where: { id: serverId }, data: { projectId } });
  revalidatePath(`/dashboard/servers/${serverId}`);
}

// ---------- Notifications ----------

export async function markNotificationsRead() {
  const user = await requireUser();
  await db.notification.updateMany({
    where: { userId: user.id, readAt: null },
    data: { readAt: new Date() },
  });
  revalidatePath("/dashboard");
}

// ---------- Password reset (email-based) ----------

export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
  // This lookup was ALREADY lowercasing while register/login stored the address
  // verbatim, which is precisely why a `Alice@Example.com` signup could never be
  // reset. Both sides now share one definition rather than two that agreed by
  // luck — see lib/email-normalize.ts.
  const email = normalizeEmail(formData.get("email"));
  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
  // and enumeration probing. On limit, still report success below (no leak).
  //
  // `clientIp` rather than the first `x-forwarded-for` entry, which is a field
  // the CALLER fills in (nginx appends the real address, it does not replace the
  // header). Keying on it let one script vary the fake value per request and get
  // a fresh 5-attempt allowance every time, which mattered twice over here: it
  // uncapped the reset-mail flood AND it removed the cap on the timing probe
  // below.
  const ip = clientIp(await headers());
  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
  if (!rl.ok) return { sent: true };
  // Always report success (don't leak which emails exist)
  const user = await db.user.findUnique({ where: { email } });
  if (user) {
    const { randomBytes, createHash } = await import("node:crypto");
    const token = randomBytes(32).toString("base64url");
    const tokenHash = createHash("sha256").update(token).digest("hex");
    await db.passwordResetToken.create({
      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
    });
    const { sendMail, emails } = await import("./mailer");
    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
    const tpl = emails.passwordReset(link);
    // THE SEND IS DELIBERATELY NOT AWAITED, and that is a security property, not
    // an optimisation.
    //
    // "If an account exists for that email, a reset link is on its way" is the
    // right answer and is returned either way — but only ONE of the two branches
    // used to open an SMTP conversation before answering. A known address took
    // as long as the mail server did; an unknown one returned after a single
    // indexed SELECT. The wording revealed nothing and the clock revealed
    // everything, one sample per address, which is a working account-enumeration
    // oracle against a hosting provider's whole customer list. Detaching the send
    // leaves the two branches differing by one INSERT.
    //
    // Nothing is lost by not waiting: the result was already discarded, and the
    // customer was never told whether it worked. Failures are logged, and the
    // rejection is swallowed so a dead mail server can never take the process
    // down through an unhandled rejection.
    //
    // `mayDeliverTo` consults the notification policy, which classifies
    // `password_reset` as CRITICAL and returns true without even loading the
    // preferences. The call is here so the POLICY decides, not this call site: a
    // reset link is the only route back into a locked-out account, so honouring
    // an "Account email: off" checkbox here would lock the customer out of their
    // own account permanently.
    void (async () => {
      if (await mayDeliverTo(user.id, "password_reset", "email")) {
        await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
      }
    })().catch((e) => {
      console.error("[password-reset] send failed:", e);
    });
    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
  }
  return { sent: true };
}

export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
  const token = String(formData.get("token") ?? "");
  const password = String(formData.get("password") ?? "");
  if (password.length < 8) return { error: "Password must be at least 8 characters." };
  const { createHash } = await import("node:crypto");
  const tokenHash = createHash("sha256").update(token).digest("hex");
  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
  if (!row || row.usedAt || row.expiresAt < new Date()) {
    return { error: "This reset link is invalid or has expired. Request a new one." };
  }
  await db.$transaction([
    // Bump sessionVersion so any sessions predating the reset are evicted.
    db.user.update({
      where: { id: row.userId },
      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
    }),
    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
  ]);
  return { ok: true };
}

/** Admin-triggered reset: emails the client a reset link. */
export async function adminSendPasswordReset(userId: string) {
  const admin = await requireAdmin();
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) throw new Error("User not found");
  const { randomBytes, createHash } = await import("node:crypto");
  const token = randomBytes(32).toString("base64url");
  const tokenHash = createHash("sha256").update(token).digest("hex");
  await db.passwordResetToken.create({
    data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
  });
  const { sendMail, emails } = await import("./mailer");
  const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
  const tpl = emails.passwordReset(link);
  // CRITICAL (see above): support has just told the customer "check your email".
  // A preference must not be able to make that a lie.
  if (await mayDeliverTo(user.id, "password_reset", "email")) {
    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html });
  }
  await db.auditLog.create({ data: { userId: admin.id, action: "admin.password_reset_sent", detail: user.email } });
}

// ---------- Impersonation (admin) ----------

export async function impersonateUser(userId: string) {
  const admin = await requireAdmin();
  const target = await db.user.findUnique({ where: { id: userId } });
  if (!target || target.role === "ADMIN") throw new Error("Cannot impersonate this account");
  await setImpersonation(userId);
  await db.auditLog.create({
    data: { userId: admin.id, action: "admin.impersonate_start", detail: `${target.email}` },
  });
  redirect("/dashboard");
}

export async function stopImpersonating() {
  await clearImpersonation();
  redirect("/admin/users");
}

/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
export const currentUser = cache(async (): Promise<User | null> => {
  const real = await realUser();
  if (!real) return null;
  if (real.role === "ADMIN") {
    const jar = await cookies();
    const imp = jar.get(IMP_COOKIE)?.value;
    if (imp) {
      try {
        const { payload } = await jwtVerify(imp, secret);
        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
          const target = await db.user.findUnique({ where: { id: payload.sub } });
          // The token outlives the checks `impersonateUser` made when it minted
          // it (2h), so they are re-made here against the CURRENT row rather
          // than trusted from the past:
          //
          //  - suspended: `realUser` refuses to hand out a session for a
          //    suspended account, and impersonation must not be a side door that
          //    resurrects one. Reviewing a suspended abuser's account is a
          //    read-only job; it must not come with the ability to act as them.
          //  - ADMIN: refused at mint time, but a customer promoted DURING an
          //    open impersonation would otherwise turn the impersonator's
          //    `currentUser()` into an ADMIN — and `requireAdmin` is built on
          //    `currentUser`, so admin actions would run attributed to the
          //    promoted account instead of the person taking them. The rule that
          //    admins refuse to act while impersonating depends on this.
          //
          // Falling through to the real admin is the safe failure: they are
          // simply themselves again, which is visible on screen.
          if (target && !target.suspended && target.role !== "ADMIN") return target;
        }
      } catch {
        /* expired/invalid impersonation — fall through to real user */
      }
    }
  }
  return real;
});

/** Non-null when the current request is an admin impersonating a customer. */
export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") return null;
  const target = await currentUser();
  if (!target || target.id === real.id) return null;
  return { admin: real, target };
});

export async function setImpersonation(targetUserId: string) {
  const real = await realUser();
  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
  // `typ: "imp"` marks this as a grant, never a session (see assertSessionToken).
  const token = await new SignJWT({ sub: targetUserId, adminId: real.id, typ: "imp" })
    .setProtectedHeader({ alg: "HS256" })
    .setIssuedAt()
    .setExpirationTime("2h")
    .sign(secret);
  const jar = await cookies();
  jar.set(IMP_COOKIE, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: 7200,
  });
}

export async function clearImpersonation() {
  const jar = await cookies();
  jar.delete(IMP_COOKIE);
}

/**
 * Guard for wallet-debit / paid actions: refuse to run while an admin is
 * impersonating a customer. Keeps money movements attributable to the account
 * holder and prevents an admin from spending a customer's balance on their behalf.
 * Throws a friendly, user-facing error. Call at the top of every spend path.
 */
export async function assertNotImpersonating(): Promise<void> {
  const imp = await impersonating();
  if (imp) {
    throw new Error(
      "This action is disabled while impersonating a customer. Stop impersonating to continue.",
    );
  }
}

export async function requireUser(): Promise<User> {
  const user = await currentUser();
  if (!user) throw new Error("UNAUTHORIZED");
  return user;
}

export async function requireAdmin(): Promise<User> {
  const user = await requireUser();
  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
  return user;
}

/**
 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
 * per-area gating lives in lib/rbac.ts (`requireArea`).
 */
export async function requireStaff(): Promise<User> {
  const user = await realUser();
  if (!user) throw new Error("UNAUTHORIZED");
  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
    throw new Error("FORBIDDEN");
  }
  return user;
}

"use server";

import { revalidatePath } from "next/cache";
import { randomBytes } from "node:crypto";
import bcrypt from "bcryptjs";
import { db } from "./db";
import { requireUser, realUser } from "./auth";
import { generateSecret, otpauthURL, verifyTOTP } from "./totp";
import { encryptSecret } from "./crypto-box";
import { hashCode, totpSecretOf, verifyTotpForUser } from "./totp-verify";

// `totpSecretOf`, `hashCode` and `verifyTotpForUser` live in the PLAIN module
// `./totp-verify`. They must not be exported from this file: everything exported
// from a `"use server"` module becomes a network-callable server action, and
// `verifyTotpForUser` takes a caller-supplied userId with no auth and no rate
// limit — as an action it was an unauthenticated 2FA brute-force oracle that
// bypassed login()'s throttle entirely. See lib/totp-verify.ts.

/**
 * Two-factor authentication (TOTP) server actions.
 *
 * Enrolment flow:
 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
 *      stays false), and returns the otpauth URI + secret for the UI to show.
 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
 *      success `totpEnabled` flips true and backup codes are generated.
 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
 *      the account password.
 *
 * Backup codes are one-time; only their sha256 hashes are stored.
 */


/** Generate N human-friendly one-time backup codes (plaintext, for display). */
function makeBackupCodes(n = 10): string[] {
  return Array.from({ length: n }, () => {
    const raw = randomBytes(5).toString("hex"); // 10 hex chars
    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
  });
}

/**
 * Step 1: create (but do not yet activate) a TOTP secret.
 *
 * Return shape keeps `secret`/`otpauthUrl` present (empty on refusal) so the
 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
 * optional `error` is populated when enrolment is refused.
 */
export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
  const user = await requireUser();

  // Block enrolment while impersonating: the real acting account must be the
  // same account being enrolled, so an admin can't seed a customer's 2FA.
  const real = await realUser();
  if (!real || real.id !== user.id) {
    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
  }

  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
  if (user.totpEnabled === true) {
    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
  }

  const secret = generateSecret();
  // Store encrypted at rest; clear any legacy plaintext value for this account.
  await db.user.update({
    where: { id: user.id },
    data: { totpSecretEnc: encryptSecret(secret), totpSecret: null, totpEnabled: false },
  });
  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
}

/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
export async function confirmTotpEnrollment(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
  const user = await requireUser();
  const code = String(formData.get("code") ?? "");
  const secret = totpSecretOf(user);
  if (!secret) return { error: "Start enrolment first." };
  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect. Try again." };

  const backupCodes = makeBackupCodes();
  await db.user.update({
    where: { id: user.id },
    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
  revalidatePath("/dashboard/settings");
  return { ok: true, backupCodes };
}

/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
export async function regenerateBackupCodes(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; backupCodes?: string[] }> {
  const user = await requireUser();
  const code = String(formData.get("code") ?? "");
  const secret = totpSecretOf(user);
  if (!user.totpEnabled || !secret) return { error: "2FA is not enabled." };
  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect." };
  const backupCodes = makeBackupCodes();
  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
  return { backupCodes };
}

/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
export async function disableTotp(
  prev: unknown,
  formData: FormData,
): Promise<{ error?: string; ok?: boolean }> {
  const user = await requireUser();
  const proof = String(formData.get("proof") ?? "");
  if (!user.totpEnabled) return { error: "2FA is not enabled." };

  const secret = totpSecretOf(user);
  const codeValid =
    (secret ? verifyTOTP(secret, proof) : false) ||
    (await verifyTotpForUser(user.id, proof));
  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
  if (!codeValid && !passwordValid) {
    return { error: "Enter a valid authenticator code, backup code, or your password." };
  }

  await db.user.update({
    where: { id: user.id },
    data: { totpEnabled: false, totpSecret: null, totpSecretEnc: null, backupCodes: [] },
  });
  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
  revalidatePath("/dashboard/settings");
  return { ok: true };
}
