async function uniqueReferralCode(): Promise<string> {
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    const clash = await db.user.findUnique({ where: { referralCode: code } });
    if (!clash) return code;
  }
  return generateReferralCode(12);
}

async function grantSignupCredit(userId: string): Promise<void> {
  const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
  if (cents <= 0) return;
  const claimed = await db.user.updateMany({
    where: { id: userId, signupCreditCents: 0 },
    data: { balanceCents: { increment: cents }, signupCreditCents: cents },
  });
  if (claimed.count === 0) return;
  await db.walletTransaction.create({ data: { userId, amountCents: cents, description: "Welcome credit" } });
}

/** `error` is a short CODE (mirrors the Google flow's GOOGLE_ERRORS convention
 *  in app/login/page.tsx) — never a raw sentence, so nothing server-derived
 *  ever gets echoed unescaped into a `?error=` query value. */
export type DiscordAuthResult =
  | { ok: true; userId: string; isNewAccount: boolean }
  | { ok: false; error: "discord_suspended" | "discord_unverified_email" | "discord_email_taken" | "discord_error" };

/**
 * Log in (if this Discord account is already linked), or create a new Nxeon
 * account (if Discord returned a verified email that matches no existing
 * account), for the unauthenticated "Continue with Discord" flow.
 *
 * SECURITY: the one real risk in this whole feature is silently signing
 * someone into (or merging into) an account that isn't theirs. Two hard
 * rules enforce that:
 *   1. An EXISTING Nxeon account is only ever signed into via its own
 *      `discordUserId` — never derived from a matching email at login time.
 *   2. A NEW account is only ever created when Discord reports the email as
 *      `verified: true` on ITS side — an unverified email is refused
 *      outright rather than trusted for either matching or creation. If a
 *      verified email collides with an existing password-based account
 *      that has no Discord link yet, this returns an error asking them to
 *      log in normally and connect Discord from Settings — never an
 *      auto-login or silent merge.
 */
export async function loginOrSignupWithDiscord(discordUser: DiscordSelfUser, userAccessToken: string): Promise<DiscordAuthResult> {
  // 1. Already linked — this IS them, full stop.
  const linked = await db.user.findUnique({ where: { discordUserId: discordUser.id } as any, select: { id: true, suspended: true } });
  if (linked) {
    if (linked.suspended) return { ok: false, error: "discord_suspended" };
    await createSession(linked.id);
    await recordAudit(linked.id, "user.login", "discord");
    await joinAndSyncBestEffort(linked.id, discordUser.id, userAccessToken);
    return { ok: true, userId: linked.id, isNewAccount: false };
  }

  // 2. Not linked — need a verified email to go any further.
  if (!discordUser.email || !discordUser.emailVerified) {
    return { ok: false, error: "discord_unverified_email" };
  }
  const email = normalizeEmail(discordUser.email);

  // 3. Email matches an existing (password-based, unlinked) account —
  // refuse to auto-login or auto-merge. See top-of-file SECURITY note.
  const existingByEmail = await db.user.findUnique({ where: { email }, select: { id: true } });
  if (existingByEmail) {
    return { ok: false, error: "discord_email_taken" };
  }

  // 4. Genuinely new — create the account. Password-less: a long random
  // hash nobody knows, same as this account would end up with no
  // meaningfully-guessable credential either way. "Forgot password" still
  // works later if they ever want a real password too.
  const referralCode = await uniqueReferralCode();
  const randomPassword = randomBytes(32).toString("hex");
  const user = await db.user.create({
    data: {
      email,
      name: discordUser.username || "Nxeon user",
      passwordHash: await bcrypt.hash(randomPassword, 12),
      referralCode,
      discordUserId: discordUser.id,
      emailVerifiedAt: new Date(), // Discord already verified it on their side.
    } as any,
  });
  await recordAudit(user.id, "user.register", "discord");
  try {
    await grantSignupCredit(user.id);
  } catch (e) {
    console.error("[discord-auth] signup credit grant failed for", user.id, e);
  }
  await createSession(user.id);
  await joinAndSyncBestEffort(user.id, discordUser.id, userAccessToken);
  return { ok: true, userId: user.id, isNewAccount: true };
}

/** Add them to the Nxeon Discord server (guilds.join) and sync their badge roles — best-effort, never blocks login/signup. */
async function joinAndSyncBestEffort(userId: string, discordUserId: string, userAccessToken: string): Promise<void> {
  if (!(await discordEnabled())) return;
  try {
