import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { canAdministerOrg } from "@/lib/team-guard";
import { TeamView } from "@/components/nx/TeamView";

/* Team & organisation, on the concept's structure.
 *
 * Co-member EMAIL ADDRESSES are only sent to the browser for a viewer who may
 * administer the org — the same gate that authorises inviting and removing.
 * That restriction is not decoration: handing every member the full roster of
 * addresses is what made the old 2FA oracle targetable at a named account
 * (see lib/team-guard.ts). A plain member sees names and roles, not addresses.
 */
export default async function TeamPage() {
  const user = await requireUser();

  const memberships = await db.membership.findMany({
    where: { userId: user.id },
    orderBy: { createdAt: "asc" },
    include: {
      org: {
        include: {
          owner: { select: { id: true, name: true } },
          members: {
            orderBy: { createdAt: "asc" },
            include: { user: { select: { id: true, name: true, email: true } } },
          },
        },
      },
    },
  });

  /* Outstanding invitations, for the orgs this viewer administers. Nothing is
     fetched for an org they merely belong to. */
  const adminOrgIds = memberships.filter((m) => canAdministerOrg(m.role)).map((m) => m.orgId);
  const invites = adminOrgIds.length
    ? await db.orgInvite.findMany({
        where: { orgId: { in: adminOrgIds }, acceptedAt: null, revokedAt: null, expiresAt: { gt: new Date() } },
        select: { orgId: true, email: true, role: true, createdAt: true, expiresAt: true },
        orderBy: { createdAt: "desc" },
      })
    : [];

  /* The Activity tab. These are the real `org.*` rows lib/actions-teams.ts
     writes on every invite, role change, removal and departure.
     IMPORTANT, and said plainly in the tab itself: AuditLog rows carry the
     ACTOR's userId, not an orgId, so this is this viewer's own team actions —
     not a feed of everything everyone in the org did. Presenting it as the
     latter would be inventing a scope the data does not have. */
  const teamActivity = await db.auditLog.findMany({
    where: { userId: user.id, action: { startsWith: "org." } },
    select: { id: true, action: true, detail: true, createdAt: true },
    orderBy: { createdAt: "desc" },
    take: 25,
  });

  return (
    <TeamView
      me={user.id}
      activity={teamActivity.map((a) => ({
        id: a.id,
        action: a.action,
        detail: a.detail,
        at: a.createdAt.toISOString(),
      }))}
      orgs={memberships.map((m) => {
        const iAdminister = canAdministerOrg(m.role);
        return {
          id: m.orgId,
          name: m.org.name,
          myRole: m.role,
          iAdminister,
          createdAt: m.org.createdAt.toISOString(),
          ownerName: m.org.owner?.name ?? "—",
          members: m.org.members.map((mem) => ({
            id: mem.userId,
            /* The Membership row's own id — updateMemberRole/removeMember key
               off THIS, never the user id (see lib/actions-teams.ts). */
            membershipId: mem.id,
            name: mem.user.name || mem.user.email.split("@")[0],
            /* Withheld from a non-administering viewer, deliberately. */
            email: iAdminister ? mem.user.email : null,
            role: mem.role,
            joined: mem.createdAt.toISOString(),
            isMe: mem.userId === user.id,
          })),
          invites: invites
            .filter((i) => i.orgId === m.orgId)
            .map((i) => ({
              email: i.email, role: i.role,
              invited: i.createdAt.toISOString(),
              expires: i.expiresAt.toISOString(),
            })),
        };
      })}
    />
  );
}
