function DangerSection({ email }: { email: string }) {
  const [confirming, setConfirming] = useState(false);
  const [typed, setTyped] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();
  const matches = typed.trim().toLowerCase() === email.toLowerCase();

  return (
    <div className="flex flex-col gap-4">
      <Card title="Download your data" sub="Everything we hold about this account, as JSON.">
        <p className="text-[12.5px] leading-relaxed text-tx-dim">
          Your profile, servers, wallet history, invoices, domains, tickets, SSH keys and team
          memberships. Secrets and passwords are never included.
        </p>
        <Link
          href="/api/account/export"
          download
          className="mt-4 inline-flex items-center gap-2 rounded-[11px] border border-rim-hi bg-well px-4 py-2.5 text-[13px] font-semibold text-tx-dim transition hover:text-white"
        >
          <Icon name="download" size={14} tone="inherit" />
          Download my data
        </Link>
      </Card>

      <Card tone="danger" title="Delete account" sub="Permanently erase this account and everything on it.">
        <p className="text-[12.5px] leading-relaxed text-tx-dim">
          This cannot be undone. Every service has to be cancelled first — the server refuses while an
          active one remains, so an accidental click can never take a running machine with it.
        </p>

        {!confirming ? (
          <button
            type="button"
            onClick={() => setConfirming(true)}
            className="mt-4 rounded-[11px] border border-red-500/45 bg-red-500/10 px-4 py-2.5 text-[13px] font-bold text-red-300 transition hover:bg-red-500/[0.18]"
          >
            Delete my account
          </button>
        ) : (
          <div className="mt-4 flex flex-col gap-3 rounded-[12px] border border-red-500/35 bg-red-500/[0.06] p-4">
            <Field label={`Type ${email} to confirm`}>
              <input
                value={typed}
                onChange={(e) => { setTyped(e.target.value); setError(null); }}
                placeholder={email}
                className={INPUT}
              />
            </Field>
            {error && <Result error={error} />}
            <div className="flex flex-wrap items-center gap-2.5">
              <button
                type="button"
                disabled={!matches || pending}
                onClick={() => start(async () => {
                  const res = await deleteMyAccount(typed);
                  // On success the action redirects away; only errors return here.
                  if (res?.error) setError(res.error);
                })}
                className="rounded-[11px] border border-red-500/50 bg-red-500/[0.18] px-4 py-2.5 text-[13px] font-bold text-red-200 transition hover:bg-red-500/[0.28] disabled:opacity-40"
              >
                {pending ? "Deleting…" : "Permanently delete"}
              </button>
              <button
                type="button"
                onClick={() => { setConfirming(false); setTyped(""); setError(null); }}
                className="rounded-[11px] border border-rim-hi bg-well px-4 py-2.5 text-[13px] font-semibold text-tx-dim transition hover:text-white"
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </Card>
    </div>
  );
}

