import { requireUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { categoryOf } from "@/lib/nx/activity";
import { ActivityView } from "@/components/nx/ActivityView";

/* Activity, on the concept's structure.
 *
 * The category counts are computed over the SAME rows the table shows, in this
 * one place — not a separate aggregate query that could disagree with the list
 * beside it. Categorising happens on read (see lib/nx/activity.ts) so the
 * hundreds of rows written before `AuditLog.category` existed group exactly
 * like new ones, with no backfill and no history rewrite.
 */
export default async function ActivityPage({
  searchParams,
}: { searchParams: Promise<{ days?: string }> }) {
  const user = await requireUser();
  const sp = await searchParams;

  /* A closed set — this becomes a date boundary in a query. */
  const days = [7, 30, 90].includes(Number(sp.days)) ? Number(sp.days) : 30;
  const since = new Date(Date.now() - days * 86_400_000);
  const prevSince = new Date(Date.now() - days * 2 * 86_400_000);

  const [rows, prevCount, sessionCount] = await Promise.all([
    db.auditLog.findMany({
      where: { userId: user.id, createdAt: { gte: since } },
      select: {
        id: true, action: true, detail: true, target: true, ip: true,
        category: true, createdAt: true,
      },
      orderBy: { createdAt: "desc" },
      take: 400,
    }),
    /* The window immediately before this one, so "vs previous" compares like
       with like rather than against an arbitrary calendar month. */
    db.auditLog.count({
      where: { userId: user.id, createdAt: { gte: prevSince, lt: since } },
    }),
    db.userSession.count({ where: { userId: user.id, createdAt: { gte: since } } }),
  ]);

  const events = rows.map((r) => ({
    id: r.id,
    action: r.action,
    /* Stored category wins where present; older rows fall through to the same
       mapping, so the two kinds are indistinguishable in the list. */
    category: r.category ?? categoryOf(r.action),
    detail: r.detail ?? "",
    target: r.target ?? "",
    ip: r.ip ?? "",
    at: r.createdAt.toISOString(),
  }));

  const counts: Record<string, number> = {};
  for (const e of events) counts[e.category] = (counts[e.category] ?? 0) + 1;

  return (
    <ActivityView
      who={user.name || user.email.split("@")[0]}
      days={days}
      events={events}
      counts={counts}
      total={events.length}
      prevTotal={prevCount}
      /* Login sessions come from UserSession, which is new and empty until
         sign-ins start being recorded — shown as such rather than as zero. */
      sessions={sessionCount}
      sessionsTracked={sessionCount > 0}
    />
  );
}
