import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { SANDBOX } from "@/lib/sandbox";
import { listMigrationsPage } from "@/lib/actions-migrate";
import { connectAddress } from "@/lib/nx/connect-address";
import { gameSubdomainBase } from "@/lib/game-subdomain-dns";
import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
import { gamePlanSpecs, specLine } from "@/lib/nx/plan-specs";
import { GAME_DISPLAY } from "@/lib/games";
import type { DestinationServer } from "@/components/customer/migrate/DestinationPicker";
import { Icon } from "@/components/nx/Icon";
import { ServicesAurora } from "@/components/nx/ServicesAurora";
import { MigrationWizard } from "@/components/customer/MigrationWizard";
import { PastMigrations } from "@/components/customer/migrate/PastMigrations";

export const dynamic = "force-dynamic";

/* The five things the concept sells under the hero. Each is a fact about this
   engine, not a slogan: it costs nothing, it detects and moves Docker and
   databases without ever asking for DB credentials, it connects read-only over
   SSH and erases the password afterwards, it is a guided wizard, and the source
   server is never written to. */
const PITCH = [
  { icon: "gift", t: "100% free", s: "No charge, on any plan" },
  { icon: "cube", t: "Docker & databases", s: "Detected and moved for you" },
  { icon: "lock2", t: "Secure & encrypted", s: "Read-only SSH, credentials erased after" },
  { icon: "layers", t: "Guided step-by-step", s: "Five steps, nothing to script" },
  { icon: "shieldcheck", t: "Old server untouched", s: "Roll back at any point" },
];

/** The display name for a game family, or the raw key if it has none. */
function gameName(family: string | null | undefined): string | null {
  if (!family) return null;
  return GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family;
}

export default async function MigratePage({
  searchParams,
}: {
  searchParams: Promise<{ mp?: string }>;
}) {
  const user = await requireUser();
  const { mp } = await searchParams;
  const page = Math.max(1, Number.parseInt(mp ?? "1", 10) || 1);

  const [servers, history, osTemplates, gameBase] = await Promise.all([
    db.server.findMany({
      where: { userId: user.id, nxcloudInstance: { is: null } },
      orderBy: { createdAt: "desc" },
      // Everything the destination picker shows. `dedicatedIp`/`portForwards`
      // are not decoration: they are what connectAddress needs to work out the
      // address a customer can actually reach the box on.
      include: {
        plan: true,
        gamePlan: true,
        osTemplate: true,
        dedicatedIp: { select: { address: true } },
        portForwards: { select: { publicPort: true, guestPort: true } },
        node: { select: { region: true, publicIp: true } },
      },
    }),
    listMigrationsPage(page, 10),
    // Plain-OS catalog, so the compatibility panel can suggest the closest match
    // when the source distro differs from the destination server's OS.
    db.osTemplate.findMany({
      where: { active: true, category: "PLAIN_OS" },
      orderBy: { sortOrder: "asc" },
      select: { id: true, name: true, family: true, version: true },
    }),
    gameSubdomainBase(),
  ]);

  const serverOptions: DestinationServer[] = servers.map((s) => {
    const isGame = s.gamePlanId !== null;
    const region = s.node?.region ?? null;
    return {
      id: s.id,
      name: s.label || s.hostname,
      kind: isGame ? "game" : "vps",
      // The game LEADS here, unlike the My Services cards where the type
      // column already names it: on this screen the row is all the customer
      // gets, and "4 GB / 20 slots" doesn't say which game is on the box.
      // gamePlanSpecs strips the name out of the plan first so it is printed
      // once, not twice.
      specs: isGame
        ? [
            gameName(s.gamePlan?.gameFamily ?? s.osTemplate?.family) ?? "Game Server",
            gamePlanSpecs(s.gamePlan?.name, gameName(s.gamePlan?.gameFamily ?? s.osTemplate?.family), s.gamePlan?.slots),
          ].filter(Boolean).join(" — ")
        : s.plan
          ? `VPS — ${specLine(s.plan.cpuCores, s.plan.ramMB, s.plan.diskGB, s.plan.storageTier)}`
          : null,
      location: region && REGION_LABELS[region]
        ? { label: REGION_LABELS[region], country: REGION_COUNTRY[region] ?? "" }
        : null,
      address: connectAddress(s, gameBase).address,
      status: s.status,
      // Only a RUNNING box can receive a migration; the picker says so rather
      // than letting a stopped one be chosen and fail at the far end.
      online: s.status === "RUNNING",
    };
  });
  const osOptions = osTemplates.map((t) => ({ id: t.id, name: t.name, family: t.family, version: t.version }));

  return (
    <>
      <ServicesAurora />

      {/* relative + z-1: the aurora is a POSITIONED (fixed, z-0) layer, so it
          paints above ordinary static content unless the page gets its own. */}
      <div className="relative z-[1] mx-auto flex w-full max-w-[1520px] flex-col gap-5">
        {/* ── hero ─────────────────────────────────────────────────────── */}
        <header className="relative min-h-[188px] overflow-hidden rounded-[18px]">
          <span aria-hidden className="pointer-events-none absolute inset-y-0 right-0 hidden w-[50%] md:block">
            <span
              className="block h-full w-full"
              style={{
                WebkitMaskImage: "linear-gradient(180deg, transparent 0%, #000 22%, #000 72%, transparent 100%)",
                maskImage: "linear-gradient(180deg, transparent 0%, #000 22%, #000 72%, transparent 100%)",
              }}
            >
              {/* eslint-disable-next-line @next/next/no-img-element -- static hero art, not an optimizable content image */}
              <img
                src="/nx/preview/hero-racks.webp"
                alt=""
                className="h-full w-full object-cover object-center opacity-[0.7]"
              />
            </span>
          </span>

          <span aria-hidden className="absolute right-2 top-1/2 hidden -translate-y-1/2 flex-col items-end gap-[7px] xl:flex">
            {["DETECT.", "ANALYZE.", "MIGRATE.", "EFFORTLESSLY."].map((l) => (
              <span key={l} className="text-[10.5px] font-semibold uppercase tracking-[0.32em] text-[#a892ff]">{l}</span>
            ))}
          </span>

          <div className="relative max-w-[660px] px-1 pb-5 pt-6">
            <span className="text-[11px] font-extrabold uppercase tracking-[0.26em] text-[#7f9ad0]">Tools</span>
            <h1 className="mt-2 text-[38px] font-extrabold leading-[1.02] tracking-[-0.035em] text-white sm:text-[44px]">
              Server <span className="grad-text">Migration</span>
            </h1>
            <p className="mt-2.5 text-[14.5px] text-tx-dim">
              Move your files, databases and services from your current host to Nxeon — for free.
            </p>
            <p className="mt-3 text-[13px] text-tx-faint">
              Moving several servers onto one box?{" "}
              <Link href="/dashboard/migrate/consolidate" className="font-semibold text-brand-300 hover:text-white">
                Consolidate them →
              </Link>
              {/* Design surface, not a product one — same gate the route itself
                  enforces, so a customer never sees the link either. */}
              {(SANDBOX || user.role === "ADMIN") && (
                <>
                  {" · "}
                  <Link href="/dashboard/migrate/preview" className="font-semibold text-[#c4a6ff] hover:text-white">
                    Preview the stages →
                  </Link>
                </>
              )}
            </p>
          </div>
        </header>

        {/* ── what you get ─────────────────────────────────────────────── */}
        <div className="grid gap-2.5 sm:grid-cols-2 lg:grid-cols-5">
          {PITCH.map((p) => (
            <div key={p.t} className="flex items-start gap-3 rounded-[13px] border border-rim-hi bg-[rgba(6,14,36,.72)] px-3.5 py-3">
              <span className="grid h-[32px] w-[32px] flex-none place-items-center rounded-[10px] border border-[#3d7bff]/35 bg-[#3d7bff]/10">
                <Icon name={p.icon} size={14} tone="inherit" className="text-[#7fb0ff]" />
              </span>
              <span className="flex min-w-0 flex-col">
                <span className="text-[12.5px] font-bold leading-tight text-white">{p.t}</span>
                <span className="mt-0.5 text-[11px] leading-snug text-tx-faint">{p.s}</span>
              </span>
            </div>
          ))}
        </div>

        <MigrationWizard servers={serverOptions} osTemplates={osOptions} />

        <section className="mt-3 flex flex-col gap-3">
          <div className="flex flex-wrap items-baseline gap-3">
            <h2 className="text-[17px] font-extrabold text-white">Past migrations</h2>
            {history.total > 0 && (
              <span className="text-[12.5px] text-tx-faint">
                {history.total} run{history.total === 1 ? "" : "s"}
              </span>
            )}
          </div>
          <PastMigrations rows={history.rows} page={history.page} pages={history.pages} total={history.total} />
        </section>
      </div>
    </>
  );
}
