async function ownedTargetServer(serverId: string) {
  const user = await requireUser();
  const server = await db.server.findUnique({ where: { id: serverId } });
  if (!server) throw new Error("Not found");
  if (server.userId !== user.id && user.role !== "ADMIN") throw new Error("Forbidden");
  return { user, server };
}

// ---- Consolidation planning (N sources → one target) ------------------------

export type ConsolidationSourceInput = {
  label: string; // short stable label, e.g. "srv-a"
  host: string;
  scan: ScanResult; // from scanSource
  domains?: string[]; // domains this source serves (from the scan/vhosts)
};

/**
 * READ-ONLY pre-flight for consolidating several source servers onto one target.
 * Builds each source's resource inventory from its scan, runs the pure collision
 * planner (lib/migrate-consolidate.ts) and returns the auto-remap plan for the
 * operator to approve. No writes, no SSH, no engine work — just the plan. The
 * actual sequential migrations (which carry each remap in Migration.items) and
 * the engine-side application of the remap are the execution half, kept separate
 * so this preview can never mutate anything.
 */
export async function planConsolidationMigration(input: {
  serverId: string;
