        }
      : {}),
    ...(scanSnapshot ? { scan: scanSnapshot } : {}),
  };

  const migration = await db.migration.create({
    data: {
      userId: user.id,
      serverId: server.id,
      sourceHost: host,
      sourcePort: port,
      sourceUser,
      sourcePasswordEnc: encryptSecret(input.sourcePassword),
      items,
      status: "PENDING",
      progress: 0,
      step: "Queued",
    },
  });

  // Enqueue the worker job. serverId ties the job to the target (cascade delete +
  // traceability); the handler loads everything else from payload.migrationId.
  await db.job.create({
    data: {
      type: "MIGRATE",
      serverId: server.id,
      payload: { migrationId: migration.id },
    },
  });

  await db.auditLog.create({
    data: {
      userId: user.id,
      action: "migration.create",
      detail: `${migration.id} ${sourceUser}@${host}:${port} -> ${server.hostname} (${paths.length} paths, ${plan.dbEngines.length} db engine(s), ${plan.composeDirs.length} compose)`,
    },
  });

  revalidatePath("/dashboard/migrate");
