function ApiSection({ keys }: {
  keys: { id: string; name: string; prefix: string; scope: string; lastUsed: string | null; created: string }[];
}) {
  const [state, action, pending] = useActionState(createApiKey, undefined);

  return (
    <div className="flex flex-col gap-4">
      <Card title="Create an API key" sub="Shown once, at creation — only a hash is stored.">
        <form action={action} className="flex flex-col gap-4">
          <div className="grid gap-4 sm:grid-cols-[minmax(0,1fr)_200px]">
            <Field label="Name">
              <input name="name" maxLength={60} placeholder="CI pipeline" required className={INPUT} />
            </Field>
            <Field label="Scope">
              <Select name="scope" defaultValue="servers:read">
                <option value="servers:read">servers:read</option>
                <option value="metrics:read">metrics:read</option>
                <option value="full">full</option>
              </Select>
            </Field>
          </div>
          <div className="flex flex-wrap items-center gap-3">
            <button type="submit" disabled={pending} className="nx-cta px-5 py-2.5 text-[13px] disabled:opacity-60">
              {pending ? "Creating…" : "Create key"}
            </button>
            <Result error={state?.error} />
          </div>
          {state?.value && (
            <div className="rounded-[12px] border border-emerald-500/35 bg-emerald-500/[0.07] p-4">
              <p className="text-[13px] font-bold text-emerald-300">Copy this now</p>
              <code className="mt-2 block break-all font-mono text-[12.5px] text-white">{state.value}</code>
            </div>
          )}
        </form>
      </Card>

      <Card title="Your keys" sub={`${keys.length} active`}>
        {keys.length === 0 ? (
          <p className="text-[12.5px] text-tx-faint">No API keys yet.</p>
        ) : (
          <div className="flex flex-col gap-2">
            {keys.map((k) => (
              <div key={k.id} className="flex flex-wrap items-center gap-3 rounded-[11px] border border-rim-soft bg-well px-3.5 py-2.5">
                <Icon name="terminal" size={16} className="flex-none" />
                <span className="flex min-w-[160px] flex-1 flex-col">
                  <span className="truncate text-[13px] font-semibold text-white">{k.name}</span>
                  <span className="truncate font-mono text-[11.5px] text-tx-faint">{k.prefix}… · {k.scope}</span>
                </span>
                <span className="text-[11.5px] text-tx-faint">{k.lastUsed ? `used ${fmtDate(k.lastUsed)}` : "never used"}</span>
                <RowAction onRun={() => revokeApiKey(k.id)} label="Revoke" />
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

